CREATE OR REPLACE FUNCTION public.a1_export_exact_amount_minor_v1(quantity text, rate_two_decimal text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  q_scale integer; q_numerator numeric; r_cents numeric; numerator numeric; denominator numeric; quotient numeric; remainder numeric;
BEGIN
  q_scale := coalesce(length(split_part(quantity, '.', 2)), 0);
  q_numerator := replace(quantity, '.', '')::numeric;
  r_cents := replace(rate_two_decimal, '.', '')::numeric;
  numerator := q_numerator * r_cents;
  denominator := 10 ^ q_scale;
  quotient := trunc(numerator / denominator);
  remainder := numerator - quotient * denominator;
  IF remainder = 0 THEN RETURN quotient; END IF;
  IF 2 * remainder >= denominator THEN RETURN quotient + 1; END IF;
  RETURN quotient;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'A1_EXPORT_AMOUNT_INVALID' USING ERRCODE = '23514';
END $function$

CREATE OR REPLACE FUNCTION public.a1_export_exact_two_decimal_v1(snapshot_value text, candidate text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE whole text; fraction text;
BEGIN
  IF snapshot_value IS NULL THEN RETURN false; END IF;
  whole := split_part(snapshot_value, '.', 1);
  fraction := split_part(snapshot_value, '.', 2);
  IF length(fraction) > 2 THEN RETURN false; END IF;
  RETURN (whole || '.' || rpad(fraction, 2, '0')) = candidate;
END $function$

CREATE OR REPLACE FUNCTION public.a1_export_issue_order_valid_v1(issues jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  entry jsonb; seen jsonb := '[]'::jsonb;
  prev_rank smallint; prev_ordinal integer; prev_field integer;
  cur_rank smallint; cur_ordinal integer; cur_field integer;
  fields text[] := ARRAY['identity','approval','source','version','currency','lines','quantity','unit','unitCost',
    'unitPrice','lineCost','linePrice','costType','taxable','costCode','discount','format','bytes','renderer'];
  key jsonb; first_item boolean := true;
BEGIN
  FOR entry IN SELECT * FROM jsonb_array_elements(issues) LOOP
    key := jsonb_build_array(entry->'code', entry->'lineKey', entry->'field');
    IF seen @> jsonb_build_array(key) THEN RETURN false; END IF;
    seen := seen || jsonb_build_array(key);
    cur_rank := public.a1_export_issue_class_rank_v1(entry->>'code');
    IF cur_rank IS NULL THEN RETURN false; END IF;
    cur_ordinal := CASE WHEN entry->'lineKey' = 'null'::jsonb THEN -1 ELSE substring(entry->>'lineKey' FROM 6)::integer END;
    cur_field := CASE WHEN entry->'field' = 'null'::jsonb THEN -1 ELSE array_position(fields, entry->>'field') - 1 END;
    IF NOT first_item THEN
      IF cur_rank < prev_rank THEN RETURN false; END IF;
      IF cur_rank = prev_rank THEN
        IF cur_ordinal < prev_ordinal THEN RETURN false; END IF;
        IF cur_ordinal = prev_ordinal AND cur_field < prev_field THEN RETURN false; END IF;
      END IF;
    END IF;
    prev_rank := cur_rank; prev_ordinal := cur_ordinal; prev_field := cur_field; first_item := false;
  END LOOP;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.historical_estimate_check_import_set()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  import_key uuid;
  expected_count integer;
  actual_count bigint;
  source_currency text;
  selected_total numeric;
  selected_cost numeric;
  reconciliation_status text;
BEGIN
  IF TG_TABLE_NAME = 'historical_estimate_imports' THEN
    import_key := NEW.id;
  ELSE
    import_key := NEW.import_id;
  END IF;
  SELECT i.expected_line_count, s.currency_code, i.declared_selected_total_minor,
    i.declared_selected_estimated_cost_minor, i.reconciliation_state
  INTO expected_count, source_currency, selected_total, selected_cost, reconciliation_status
  FROM public.historical_estimate_imports i
  JOIN public.historical_estimate_sources s ON s.tenant_id = i.tenant_id AND s.id = i.source_id
  WHERE i.tenant_id = NEW.tenant_id AND i.id = import_key;
  SELECT count(*) INTO actual_count
  FROM public.historical_estimate_import_lines
  WHERE tenant_id = NEW.tenant_id AND import_id = import_key;
  IF expected_count IS NULL OR actual_count IS DISTINCT FROM expected_count::bigint THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'hei_complete_line_set',
      MESSAGE = 'Historical selection requires its complete declared line set';
  END IF;
  IF source_currency IS NULL AND (selected_total IS NOT NULL OR selected_cost IS NOT NULL
      OR reconciliation_status IS DISTINCT FROM 'unresolved') THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'hei_unknown_currency',
      MESSAGE = 'Historical selection money requires an explicit supported source currency';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.historical_estimate_check_source_set()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  source_key uuid;
  expected_count integer;
  actual_count bigint;
  source_currency text;
BEGIN
  IF TG_TABLE_NAME = 'historical_estimate_sources' THEN
    source_key := NEW.id;
  ELSE
    source_key := NEW.source_id;
  END IF;
  SELECT expected_line_count, currency_code INTO expected_count, source_currency
  FROM public.historical_estimate_sources
  WHERE tenant_id = NEW.tenant_id AND id = source_key;
  SELECT count(*) INTO actual_count
  FROM public.historical_estimate_source_lines
  WHERE tenant_id = NEW.tenant_id AND source_id = source_key;
  IF expected_count IS NULL OR actual_count IS DISTINCT FROM expected_count::bigint THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'hes_complete_line_set',
      MESSAGE = 'Historical source requires its complete declared line set';
  END IF;
  IF source_currency IS NULL AND EXISTS (
    SELECT 1 FROM public.historical_estimate_source_lines
    WHERE tenant_id = NEW.tenant_id AND source_id = source_key
      AND (unit_price IS NOT NULL OR unit_estimated_cost IS NOT NULL
        OR line_price_minor IS NOT NULL OR line_estimated_cost_minor IS NOT NULL)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'hesl_unknown_currency',
      MESSAGE = 'Historical money requires an explicit supported source currency';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.historical_estimate_valid_reconciliation(report jsonb, stored_state text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  finding jsonb;
  money_key text;
BEGIN
  IF jsonb_typeof(report) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
  IF NOT (report ?& ARRAY['version','state','sumPriceMinor','sumCostMinor','findings'])
    OR report - ARRAY['version','state','sumPriceMinor','sumCostMinor','findings'] <> '{}'::jsonb
    OR report->>'version' IS DISTINCT FROM 'historical-reconciliation-v1'
    OR report->>'state' IS DISTINCT FROM stored_state
    OR stored_state NOT IN ('unresolved','matched','mismatch')
  THEN RETURN false; END IF;
  FOREACH money_key IN ARRAY ARRAY['sumPriceMinor','sumCostMinor'] LOOP
    IF report->money_key <> 'null'::jsonb AND
      (jsonb_typeof(report->money_key) IS DISTINCT FROM 'string'
       OR (report->>money_key) !~ '^(0|[1-9][0-9]{0,19})$')
    THEN RETURN false; END IF;
  END LOOP;
  IF jsonb_typeof(report->'findings') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
  IF jsonb_array_length(report->'findings') > 4002 THEN RETURN false; END IF;
  FOR finding IN SELECT value FROM jsonb_array_elements(report->'findings') LOOP
    IF jsonb_typeof(finding) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
    IF NOT (finding ?& ARRAY['code','field'])
      OR finding - ARRAY['code','field','sourceLineKey','expectedMinor','actualMinor'] <> '{}'::jsonb
      OR jsonb_typeof(finding->'code') IS DISTINCT FROM 'string'
      OR finding->>'code' NOT IN ('unknown_currency','missing_line_price','missing_line_cost',
        'missing_declared_total','missing_declared_cost','price_total_mismatch','cost_total_mismatch',
        'price_extension_mismatch','cost_extension_mismatch','fractional_minor_extension','incomplete_extension')
      OR jsonb_typeof(finding->'field') IS DISTINCT FROM 'string'
      OR finding->>'field' NOT IN ('currency','price','cost')
    THEN RETURN false; END IF;
    IF finding ? 'sourceLineKey' AND (jsonb_typeof(finding->'sourceLineKey') IS DISTINCT FROM 'string'
      OR length(finding->>'sourceLineKey') NOT BETWEEN 1 AND 128)
    THEN RETURN false; END IF;
    IF finding ? 'expectedMinor' AND (jsonb_typeof(finding->'expectedMinor') IS DISTINCT FROM 'string'
      OR (finding->>'expectedMinor') !~ '^(0|[1-9][0-9]{0,29})$')
    THEN RETURN false; END IF;
    IF finding ? 'actualMinor' AND (jsonb_typeof(finding->'actualMinor') IS DISTINCT FROM 'string'
      OR (finding->>'actualMinor') !~ '^(0|[1-9][0-9]{0,19})$')
    THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.internal_approval_check_final_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE target uuid;d public.estimate_drafts;s public.estimate_internal_approval_snapshots;a public.estimate_internal_approvals;r public.estimate_internal_approval_revocations;child public.estimate_drafts;parent public.estimate_drafts;initial_evidence boolean:=TG_TABLE_NAME IN ('estimate_internal_approval_snapshots','estimate_internal_approvals');
BEGIN
 IF TG_TABLE_NAME='estimate_drafts' THEN target:=NEW.id;ELSE target:=NEW.estimate_draft_id;END IF;
 SELECT * INTO d FROM public.estimate_drafts WHERE id=target FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'A1_DRAFT_MISSING' USING ERRCODE='23514';END IF;
 SELECT * INTO s FROM public.estimate_internal_approval_snapshots WHERE estimate_draft_id=target;
 SELECT * INTO a FROM public.estimate_internal_approvals WHERE estimate_draft_id=target;
 SELECT * INTO r FROM public.estimate_internal_approval_revocations WHERE estimate_draft_id=target;
 IF s.id IS NULL AND a.id IS NULL AND r.id IS NULL THEN
  IF d.status IN ('internally_approved','internal_approval_revoked') THEN RAISE EXCEPTION 'A1_DECISION_PAIR_MISSING' USING ERRCODE='23514';END IF;
 ELSE
  IF s.id IS NULL OR a.id IS NULL OR a.snapshot_id<>s.id OR a.approved_by<>s.captured_by OR a.approved_at<>s.created_at OR d.version<>s.draft_version OR d.approved_by IS DISTINCT FROM a.approved_by OR d.approved_at IS DISTINCT FROM a.approved_at OR d.locked_at IS DISTINCT FROM a.approved_at OR (r.id IS NULL AND d.status<>'internally_approved') OR (r.id IS NOT NULL AND (d.status<>'internal_approval_revoked' OR r.revoked_at<a.approved_at)) THEN RAISE EXCEPTION 'A1_DECISION_STATE_MISMATCH' USING ERRCODE='23514';END IF;
  IF public.internal_approval_draft_matches_v1(d,s.snapshot_payload,initial_evidence) IS NOT TRUE THEN RAISE EXCEPTION 'A1_DRAFT_SNAPSHOT_MISMATCH' USING ERRCODE='23514';END IF;
  PERFORM public.internal_approval_check_lineage_v1(d.id);
 END IF;
 IF d.a1_version_request_id IS NOT NULL THEN
  SELECT * INTO parent FROM public.estimate_drafts WHERE id=d.supersedes_id FOR KEY SHARE;
  IF NOT FOUND OR parent.tenant_id IS DISTINCT FROM d.tenant_id OR parent.project_id IS DISTINCT FROM d.project_id OR parent.client_id IS DISTINCT FROM d.client_id OR parent.superseded_by IS DISTINCT FROM d.id THEN RAISE EXCEPTION 'A1_VERSION_CONTEXT_MISMATCH' USING ERRCODE='23514';END IF;
  PERFORM public.internal_approval_check_lineage_v1(d.id);
 END IF;
 SELECT * INTO child FROM public.estimate_drafts WHERE supersedes_id=d.id AND a1_version_request_id IS NOT NULL;
 IF FOUND AND (child.tenant_id IS DISTINCT FROM d.tenant_id OR child.project_id IS DISTINCT FROM d.project_id OR child.client_id IS DISTINCT FROM d.client_id OR d.superseded_by IS DISTINCT FROM child.id) THEN RAISE EXCEPTION 'A1_VERSION_CONTEXT_MISMATCH' USING ERRCODE='23514';END IF;
 IF s.id IS NOT NULL AND d.superseded_by IS NOT NULL AND (child.id IS NULL OR child.id<>d.superseded_by) THEN RAISE EXCEPTION 'A1_VERSION_SUCCESSOR_MISSING' USING ERRCODE='23514';END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.internal_approval_check_lineage_v1(root_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE root_d public.estimate_drafts;d public.estimate_drafts;stack jsonb;entry jsonb;path jsonb;seen uuid[]:='{}'::uuid[];current_id uuid;parent_id uuid;n integer:=0;
BEGIN
 SELECT * INTO root_d FROM public.estimate_drafts WHERE id=root_id;
 IF NOT FOUND OR root_d.tenant_id IS NULL OR root_d.client_id IS NULL THEN RAISE EXCEPTION 'A1_LINEAGE_CONTEXT_INVALID' USING ERRCODE='23514'; END IF;
 stack:=jsonb_build_array(jsonb_build_object('id',root_id,'path','[]'::jsonb));
 WHILE jsonb_array_length(stack)>0 LOOP
  entry:=stack->0;stack:=stack-0;current_id:=(entry->>'id')::uuid;path:=entry->'path';
  IF path @> jsonb_build_array(current_id::text) THEN RAISE EXCEPTION 'A1_LINEAGE_CYCLE' USING ERRCODE='23514';END IF;
  IF current_id=ANY(seen) THEN CONTINUE;END IF;
  n:=n+1;IF n>1000 THEN RAISE EXCEPTION 'A1_LINEAGE_LIMIT' USING ERRCODE='23514';END IF;
  SELECT * INTO d FROM public.estimate_drafts WHERE id=current_id FOR KEY SHARE;
  IF NOT FOUND OR d.tenant_id IS DISTINCT FROM root_d.tenant_id OR d.project_id IS DISTINCT FROM root_d.project_id OR d.client_id IS DISTINCT FROM root_d.client_id THEN RAISE EXCEPTION 'A1_LINEAGE_CONTEXT_INVALID' USING ERRCODE='23514';END IF;
  IF d.source IS NULL OR d.source NOT IN ('assembly_calculator','scope_draft','version','change_order') OR EXISTS(SELECT 1 FROM public.historical_estimate_imports h WHERE h.estimate_draft_id=d.id) THEN RAISE EXCEPTION 'A1_LINEAGE_SOURCE_INVALID' USING ERRCODE='23514';END IF;
  IF d.source='version' AND d.supersedes_id IS NULL OR d.source='change_order' AND d.change_order_of IS NULL THEN RAISE EXCEPTION 'A1_LINEAGE_PARENT_MISSING' USING ERRCODE='23514';END IF;
  seen:=array_append(seen,current_id);path:=path||jsonb_build_array(current_id::text);
  FOR parent_id IN SELECT DISTINCT p FROM unnest(ARRAY[d.supersedes_id,d.change_order_of]) AS p WHERE p IS NOT NULL ORDER BY p LOOP
   stack:=jsonb_build_array(jsonb_build_object('id',parent_id,'path',path))||stack;
  END LOOP;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.internal_approval_draft_matches_v1(d public.estimate_drafts, s jsonb, include_notes boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f jsonb:=s->'financials';o jsonb:=s->'origin';pc jsonb:=s->'commercialContext'->'pricingContext';p jsonb:=s->'commercialContext'->'policyContext';raw jsonb;item jsonb;i integer;candidate text;resolved text;raw_risk text;raw_channel text;basis text;
BEGIN
 IF d.source IS DISTINCT FROM o->>'source' OR date_trunc('milliseconds',d.created_at) IS DISTINCT FROM (o->>'sourceCreatedAt')::timestamptz OR public.internal_approval_trim_v1(replace(replace(d.pricing_schema_version,E'
',E'
'),E'',E'
')) IS DISTINCT FROM o->>'pricingSchemaVersion' OR d.estimate_id::text IS DISTINCT FROM o->>'estimateId' OR d.intake_form_id::text IS DISTINCT FROM o->>'intakeFormId' OR d.bundle_id::text IS DISTINCT FROM o->>'bundleId' OR d.supersedes_id::text IS DISTINCT FROM o->>'supersedesId' OR d.change_order_of::text IS DISTINCT FROM o->>'changeOrderOf' THEN RETURN false; END IF;
 IF d.bundle_name IS NOT NULL AND public.internal_approval_trim_v1(replace(replace(d.bundle_name,E'
',E'
'),E'',E'
')) IS DISTINCT FROM s->'presentation'->>'bundleName' OR d.bundle_name IS NULL AND s->'presentation'->'bundleName'<>'null'::jsonb THEN RETURN false; END IF;
 IF include_notes AND replace(replace(d.notes,E'
',E'
'),E'',E'
') IS DISTINCT FROM s->'presentation'->>'reviewedNotes' THEN RETURN false; END IF;
 IF d.subtotal_price*100 IS DISTINCT FROM (f->>'subtotalPriceMinor')::numeric OR d.discount_amount*100 IS DISTINCT FROM (f->>'discountMinor')::numeric OR d.final_total_price*100 IS DISTINCT FROM (f->>'finalPriceMinor')::numeric OR d.subtotal_cost*100 IS DISTINCT FROM (f->>'estimatedCostMinor')::numeric OR to_jsonb(d.discount_applied) IS DISTINCT FROM f->'discountApplied' THEN RETURN false; END IF;
 IF d.scope_draft_id::text IS DISTINCT FROM s->'scopeReference'->>'scopeDraftId' THEN RETURN false; END IF;
 IF public.internal_approval_trim_v1(replace(replace(d.finish_level,E'
',E'
'),E'',E'
')) IS DISTINCT FROM pc->>'finishLevel' OR public.internal_approval_trim_v1(replace(replace(d.region,E'
',E'
'),E'',E'
')) IS DISTINCT FROM pc->>'region' OR public.internal_approval_trim_v1(replace(replace(d.zone,E'
',E'
'),E'',E'
')) IS DISTINCT FROM pc->>'zone' OR public.internal_approval_trim_v1(replace(replace(d.trade,E'
',E'
'),E'',E'
')) IS DISTINCT FROM pc->>'trade' OR d.coastal_modifier IS DISTINCT FROM (pc->>'coastalModifier')::numeric THEN RETURN false; END IF;
 IF d.channel IS NOT NULL AND public.internal_approval_pricing_channel_v1(d.channel) IS DISTINCT FROM pc->>'pricingChannel' OR d.channel IS NULL AND pc->'pricingChannel'<>'null'::jsonb THEN RETURN false; END IF;
 raw_channel:=coalesce(d.commercial_channel,d.pricing_snapshot->>'commercialChannel',d.draft_data->>'commercialChannel');
 IF public.internal_approval_channel_v1(raw_channel) IS DISTINCT FROM pc->>'storedCommercialChannel' THEN RETURN false; END IF;
 raw_risk:=coalesce(d.pricing_snapshot->>'geoRiskClass',d.draft_data->>'geoRiskClass');
 IF raw_risk IS DISTINCT FROM pc->>'storedGeoRiskClass' OR (raw_risk IS NULL) IS DISTINCT FROM (pc->>'storedRiskBasis'='unknown') THEN RETURN false; END IF;
 IF d.commercial_channel IS NOT NULL THEN candidate:=d.commercial_channel;basis:='draft.commercialChannel';
 ELSIF d.pricing_snapshot->>'commercialChannel' IS NOT NULL THEN candidate:=d.pricing_snapshot->>'commercialChannel';basis:='draft.pricingSnapshot.commercialChannel';
 ELSIF d.draft_data->>'commercialChannel' IS NOT NULL THEN candidate:=d.draft_data->>'commercialChannel';basis:='draft.draftData.commercialChannel';
 ELSE candidate:=d.channel;basis:='draft.channel_mapping';END IF;
 IF public.internal_approval_trim_v1(replace(replace(candidate,E'
',E'
'),E'',E'
')) IS DISTINCT FROM p->>'channelRawValue' OR basis IS DISTINCT FROM p->>'channelBasis' THEN RETURN false; END IF;
 FOREACH candidate IN ARRAY ARRAY[d.commercial_channel,d.pricing_snapshot->>'commercialChannel',d.draft_data->>'commercialChannel'] LOOP
  IF candidate IS NOT NULL THEN resolved:=public.internal_approval_channel_v1(candidate);IF resolved IS NULL OR resolved<>p->>'commercialChannel' THEN RETURN false;END IF;END IF;
 END LOOP;
 IF d.channel IS NOT NULL AND public.internal_approval_channel_v1(public.internal_approval_pricing_channel_v1(d.channel)) IS DISTINCT FROM p->>'commercialChannel' THEN RETURN false;END IF;
 IF jsonb_typeof(d.line_items) IS DISTINCT FROM 'array' OR jsonb_array_length(d.line_items)<>jsonb_array_length(s->'lines') OR jsonb_typeof(d.assembly_selections) IS DISTINCT FROM 'array' OR jsonb_array_length(d.assembly_selections)<>jsonb_array_length(s->'assemblySelections') THEN RETURN false; END IF;
 FOR i IN 0..jsonb_array_length(s->'lines')-1 LOOP
  raw:=d.line_items->i;item:=s->'lines'->i;
  IF public.internal_approval_trim_v1(replace(replace(raw->>'costGroupName',E'
',E'
'),E'',E'
')) IS DISTINCT FROM item->>'costGroupName' OR public.internal_approval_trim_v1(replace(replace(raw->>'costItemName',E'
',E'
'),E'',E'
')) IS DISTINCT FROM item->>'costItemName' OR replace(replace(raw->>'description',E'
',E'
'),E'',E'
') IS DISTINCT FROM item->>'description' OR public.internal_approval_trim_v1(replace(replace(raw->>'unit',E'
',E'
'),E'',E'
')) IS DISTINCT FROM item->>'unit' OR raw->>'assemblyId' IS DISTINCT FROM item->>'assemblyId' OR public.internal_approval_trim_v1(replace(replace(raw->>'costCode',E'
',E'
'),E'',E'
')) IS DISTINCT FROM item->>'costCode' OR coalesce(raw->'taxable','null'::jsonb) IS DISTINCT FROM item->'taxable' THEN RETURN false; END IF;
  IF public.internal_approval_legacy_number_v1(raw->'quantity',6) IS DISTINCT FROM (item->>'quantity')::numeric OR public.internal_approval_legacy_number_v1(raw->'unitCostSnapshot',6) IS DISTINCT FROM (item->>'unitCostSnapshot')::numeric OR public.internal_approval_legacy_number_v1(raw->'unitPriceSnapshot',6) IS DISTINCT FROM (item->>'unitPriceSnapshot')::numeric OR public.internal_approval_legacy_number_v1(raw->'lineTotalCost',2)*100 IS DISTINCT FROM (item->>'lineTotalCostMinor')::numeric OR public.internal_approval_legacy_number_v1(raw->'lineTotalPrice',2)*100 IS DISTINCT FROM (item->>'lineTotalPriceMinor')::numeric THEN RETURN false; END IF;
 END LOOP;
 IF d.assembly_count IS NOT NULL AND d.assembly_count<>jsonb_array_length(s->'assemblySelections') THEN RETURN false; END IF;
 FOR i IN 0..jsonb_array_length(s->'assemblySelections')-1 LOOP
  raw:=d.assembly_selections->i;item:=s->'assemblySelections'->i;
  IF raw->>'assemblyId' IS DISTINCT FROM item->>'assemblyId' OR public.internal_approval_trim_v1(replace(replace(raw->>'assemblyName',E'
',E'
'),E'',E'
')) IS DISTINCT FROM item->>'assemblyName' OR public.internal_approval_trim_v1(replace(replace(raw->>'assemblyCode',E'
',E'
'),E'',E'
')) IS DISTINCT FROM item->>'assemblyCode' OR public.internal_approval_trim_v1(replace(replace(raw->>'category',E'
',E'
'),E'',E'
')) IS DISTINCT FROM item->>'category' OR public.internal_approval_legacy_number_v1(raw->'quantity',6) IS DISTINCT FROM (item->>'quantity')::numeric OR public.internal_approval_legacy_number_v1(raw->'unitCost',6) IS DISTINCT FROM (item->>'unitCost')::numeric OR public.internal_approval_legacy_number_v1(raw->'unitPrice',6) IS DISTINCT FROM (item->>'unitPrice')::numeric OR public.internal_approval_legacy_number_v1(raw->'extendedCost',2)*100 IS DISTINCT FROM (item->>'extendedCostMinor')::numeric OR public.internal_approval_legacy_number_v1(raw->'extendedPrice',2)*100 IS DISTINCT FROM (item->>'extendedPriceMinor')::numeric THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.internal_approval_historical_project_witness_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  affected integer;
BEGIN
  UPDATE public.projects AS parent
     SET updated_at = parent.updated_at
   WHERE parent.id = NEW.project_id
     AND parent.tenant_id = NEW.tenant_id
     AND parent.client_id = NEW.client_id;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'A1_HISTORICAL_PROJECT_UNAVAILABLE' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.internal_approval_legacy_number_v1(value jsonb, scale_limit integer)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE scalar text;
BEGIN
 IF value IS NULL OR value='null'::jsonb THEN RETURN NULL; END IF;
 IF jsonb_typeof(value) NOT IN ('number','string') THEN RAISE EXCEPTION 'A1_SOURCE_NUMBER_INVALID' USING ERRCODE='23514'; END IF;
 scalar:=value#>>'{}';
 IF scalar!~('^(0|[1-9][0-9]{0,'||CASE WHEN scale_limit=2 THEN '17' ELSE '13' END||'})(\.[0-9]{1,'||scale_limit::text||'})?$') THEN RAISE EXCEPTION 'A1_SOURCE_NUMBER_INVALID' USING ERRCODE='23514'; END IF;
 RETURN scalar::numeric;
END $function$

CREATE OR REPLACE FUNCTION public.internal_approval_matches_v1(value jsonb, shape jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE kind text:=shape->>'type'; scalar text; item jsonb; entry record; keys text[];
BEGIN
  IF value IS NULL THEN RETURN false; END IF;
  IF value='null'::jsonb THEN RETURN coalesce((shape->>'nullable')::boolean,false); END IF;
  IF kind='object' THEN
    IF jsonb_typeof(value)<>'object' THEN RETURN false; END IF;
    SELECT array_agg(k) INTO keys FROM jsonb_object_keys(shape->'properties') AS k;
    IF NOT (value ?& keys) OR value-keys<>'{}'::jsonb THEN RETURN false; END IF;
    FOR entry IN SELECT * FROM jsonb_each(shape->'properties') LOOP
      IF public.internal_approval_matches_v1(value->entry.key,entry.value) IS NOT TRUE THEN RETURN false; END IF;
    END LOOP;
    RETURN true;
  ELSIF kind='array' THEN
    IF jsonb_typeof(value)<>'array' OR jsonb_array_length(value)<(shape->>'min')::integer OR jsonb_array_length(value)>(shape->>'max')::integer THEN RETURN false; END IF;
    FOR item IN SELECT * FROM jsonb_array_elements(value) LOOP
      IF public.internal_approval_matches_v1(item,shape->'items') IS NOT TRUE THEN RETURN false; END IF;
    END LOOP;
    RETURN true;
  ELSIF kind='enum' THEN RETURN (shape->'values') @> jsonb_build_array(value);
  ELSIF kind='boolean' THEN RETURN jsonb_typeof(value)='boolean';
  ELSIF kind='integer' THEN
    RETURN jsonb_typeof(value)='number' AND (value#>>'{}')~'^[0-9]+$' AND (value#>>'{}')::numeric BETWEEN (shape->>'min')::numeric AND (shape->>'max')::numeric;
  END IF;
  IF jsonb_typeof(value)<>'string' THEN RETURN false; END IF;
  scalar:=value#>>'{}';
  IF kind='uuid' THEN RETURN scalar~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND scalar<>'00000000-0000-0000-0000-000000000000';
  ELSIF kind='hash' THEN RETURN scalar~'^[0-9a-f]{64}$';
  ELSIF kind='minor' THEN RETURN scalar~'^(0|[1-9][0-9]{0,19})$';
  ELSIF kind='signed_minor' THEN RETURN scalar~'^(0|-?[1-9][0-9]{0,19})$';
  ELSIF kind IN ('decimal','positive_decimal','percent') THEN
    IF scalar!~'^(0|[1-9][0-9]{0,13})(\.[0-9]{0,5}[1-9])?$' THEN RETURN false; END IF;
    RETURN (kind<>'positive_decimal' OR scalar::numeric>0) AND (kind<>'percent' OR scalar::numeric<=100);
  ELSIF kind IN ('label','code') THEN
    RETURN char_length(scalar) BETWEEN 1 AND CASE WHEN kind='label' THEN 255 ELSE 128 END AND scalar=public.internal_approval_trim_v1(scalar) AND position(chr(13) IN scalar)=0;
  ELSIF kind='text' THEN RETURN char_length(scalar)<=5000 AND position(chr(13) IN scalar)=0;
  ELSIF kind='timestamp' THEN
    RETURN scalar~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'
      AND to_char(scalar::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')=scalar;
  END IF;
  RETURN false;
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR invalid_datetime_format OR numeric_value_out_of_range THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.internal_approval_membership_parent_version_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  affected integer;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.project_id IS NOT DISTINCT FROM OLD.project_id
       AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id THEN
      RETURN NEW;
    END IF;
  END IF;

  -- Preserve visible dates while creating the MVCC version observed by the
  -- approval's project lock. This write rolls back with the membership write.
  UPDATE public.projects AS parent
     SET updated_at = parent.updated_at
   WHERE parent.id = NEW.project_id;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'A1_MEMBERSHIP_PROJECT_UNAVAILABLE' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.internal_approval_policy_parent_version_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  affected integer;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.tenant_id IS NOT DISTINCT FROM OLD.tenant_id THEN
      RETURN NEW;
    END IF;
  END IF;

  UPDATE public.tenants AS parent
     SET updated_at = parent.updated_at
   WHERE parent.id = NEW.tenant_id;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'A1_POLICY_TENANT_UNAVAILABLE' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.internal_approval_valid_snapshot_v1(snapshot jsonb, evaluation jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f jsonb; p jsonb; pricing jsonb; geo jsonb; settings jsonb; floors jsonb; item jsonb; classification jsonb;
        total_price numeric:=0;total_cost numeric:=0;price numeric;cost numeric;floor numeric;channel_floor numeric;geo_floor numeric;
        position integer:=0; expected_warnings jsonb:='[]'::jsonb; expected_evaluation jsonb; warning text;last_warning integer:=0;warning_position integer;
BEGIN
 IF public.internal_approval_matches_v1(snapshot,public.internal_approval_snapshot_shape_v1()) IS NOT TRUE OR public.internal_approval_matches_v1(evaluation,public.internal_approval_evaluation_shape_v1()) IS NOT TRUE THEN RETURN false; END IF;
 f:=snapshot->'financials';p:=snapshot->'commercialContext'->'policyContext';pricing:=snapshot->'commercialContext'->'pricingContext';
 geo:=p->'projectGeo';settings:=p->'tenantSettings';floors:=p->'floors';
 price:=(f->>'finalPriceMinor')::numeric;cost:=(f->>'estimatedCostMinor')::numeric;
 IF price<=0 OR (f->>'subtotalPriceMinor')::numeric-(f->>'discountMinor')::numeric<>price OR (f->>'discountMinor')::numeric>(f->>'subtotalPriceMinor')::numeric OR (f->'discountApplied'='false'::jsonb AND f->>'discountMinor'<>'0') THEN RETURN false; END IF;
 IF snapshot->'origin'->>'source'='version' AND snapshot->'origin'->'supersedesId'='null'::jsonb OR snapshot->'origin'->>'source'='change_order' AND snapshot->'origin'->'changeOrderOf'='null'::jsonb THEN RETURN false; END IF;
 IF snapshot->'scopeReference'->'reviewSnapshotId'<>'null'::jsonb OR (snapshot->'scopeReference'->>'association'='none') IS DISTINCT FROM (snapshot->'scopeReference'->'scopeDraftId'='null'::jsonb) THEN RETURN false; END IF;
 IF (settings->'settingsId'='null'::jsonb) IS DISTINCT FROM (settings->'settingsUpdatedAt'='null'::jsonb) OR (settings->'settingsId'='null'::jsonb AND (settings->'channelOverridePct'<>'null'::jsonb OR settings->'geoOverridePct'<>'null'::jsonb)) THEN RETURN false; END IF;
 IF geo->>'zoneTenantId' IS DISTINCT FROM snapshot->'identity'->>'tenantId' OR (CASE WHEN p->>'channelBasis'='draft.channel_mapping' THEN public.internal_approval_channel_v1(public.internal_approval_pricing_channel_v1(p->>'channelRawValue')) ELSE public.internal_approval_channel_v1(p->>'channelRawValue') END) IS DISTINCT FROM p->>'commercialChannel' THEN RETURN false; END IF;
 IF pricing->'storedCommercialChannel'<>'null'::jsonb AND pricing->>'storedCommercialChannel'<>p->>'commercialChannel' OR pricing->'storedGeoRiskClass'<>'null'::jsonb AND pricing->>'storedGeoRiskClass'<>p->>'geoRiskClass' OR ((pricing->>'storedRiskBasis'='unknown') IS DISTINCT FROM (pricing->'storedGeoRiskClass'='null'::jsonb)) OR (pricing->'zone'<>'null'::jsonb AND pricing->'zone' IS DISTINCT FROM geo->'zone') THEN RETURN false; END IF;
 IF geo->>'coastalExposureLevel' IN ('moderate','high','extreme') THEN
  IF geo->>'riskResolutionBasis'<>'zone_exposure' OR p->>'geoRiskClass'<>(CASE WHEN geo->>'coastalExposureLevel'='extreme' THEN 'barrier_island' ELSE 'coastal' END) THEN RETURN false; END IF;
 ELSE
  IF geo->>'riskResolutionBasis'<>'persisted_project_risk' OR geo->>'persistedProjectRiskClass' IS DISTINCT FROM p->>'geoRiskClass' OR p->>'geoRiskClass' IS DISTINCT FROM (CASE WHEN lower(geo->>'zone')~'barrier|isle of palms|sullivan|folly|kiawah|seabrook|edisto|dewees|capers|island' THEN 'barrier_island' WHEN lower(geo->>'zone')~'coastal|beach|waterfront|marsh|tidal|harbor|creek|sound|peninsula' THEN 'coastal' ELSE 'inland' END) THEN RETURN false; END IF;
 END IF;
 IF geo->'persistedProjectRiskClass'<>'null'::jsonb AND geo->>'persistedProjectRiskClass'<>p->>'geoRiskClass' THEN RETURN false; END IF;
 FOR warning IN SELECT jsonb_array_elements_text(geo->'warningCodes') LOOP
  warning_position:=array_position(ARRAY['geo.geocode_failed','geo.geocode_low_confidence','geo.zone_not_detected','geo.coastal_exposure','geo.barrier_island_exposure','geo.outside_service_radius','geo.high_cost_multiplier'],warning);
  IF warning_position<=3 OR warning_position<=last_warning THEN RETURN false; END IF;last_warning:=warning_position;
 END LOOP;
 IF (p->>'geoRiskClass'='barrier_island' AND NOT(geo->'warningCodes' ? 'geo.barrier_island_exposure')) OR (p->>'geoRiskClass'='coastal' AND NOT(geo->'warningCodes' ? 'geo.coastal_exposure')) OR ((geo->>'costMultiplier')::numeric>=1.15 AND NOT(geo->'warningCodes' ? 'geo.high_cost_multiplier')) THEN RETURN false; END IF;
 channel_floor:=CASE p->>'commercialChannel' WHEN 'premium' THEN 28 WHEN 'trade' THEN 18 ELSE 15 END;
 geo_floor:=CASE p->>'geoRiskClass' WHEN 'inland' THEN 0 WHEN 'coastal' THEN 42 ELSE 50 END;
 floor:=greatest(channel_floor,geo_floor,(settings->>'channelOverridePct')::numeric,(settings->>'geoOverridePct')::numeric);
 IF (floors->>'channelBasePct')::numeric<>channel_floor OR (floors->>'geoBasePct')::numeric<>geo_floor OR (floors->>'effectiveFloorPct')::numeric<>floor OR floors->>'floorKind'<>(CASE WHEN p->>'commercialChannel'='capital' THEN 'fee' ELSE 'margin' END) OR (geo->>'zoneMinFloorPct')::numeric>floor THEN RETURN false; END IF;
 FOR item IN SELECT * FROM jsonb_array_elements(snapshot->'lines') LOOP
  position:=position+1;
  IF item->>'lineKey'<>'line:'||position::text OR (item->>'ordinal')::integer<>position THEN RETURN false; END IF;
  total_price:=total_price+(item->>'lineTotalPriceMinor')::numeric;total_cost:=total_cost+(item->>'lineTotalCostMinor')::numeric;
  classification:=item->'csvClassification';
  IF classification<>'null'::jsonb THEN
   IF item->'unit'='null'::jsonb OR item->'unitCostSnapshot'='null'::jsonb OR item->'unitPriceSnapshot'='null'::jsonb THEN RETURN false; END IF;
   IF (classification->>'costCodeSource'='unknown') IS DISTINCT FROM (classification->'costCode'='null'::jsonb) THEN RETURN false; END IF;
   IF classification->>'unitSource'='stored_canonical' AND classification->>'normalizedUnit' IS DISTINCT FROM item->>'unit' THEN RETURN false; END IF;
   IF classification->>'costCodeSource'='stored' THEN
    IF item->'costCode'='null'::jsonb OR classification->'costCode' IS DISTINCT FROM item->'costCode' THEN RETURN false; END IF;
   ELSIF item->'costCode'<>'null'::jsonb THEN RETURN false; END IF;
  END IF;
 END LOOP;
 IF total_price<>(f->>'subtotalPriceMinor')::numeric OR total_cost<>cost THEN RETURN false; END IF;
 IF 100*(price-cost)<floor*price THEN RETURN false; END IF;
 IF 100*(price-cost)<35*price THEN expected_warnings:=expected_warnings||jsonb_build_array(jsonb_build_object('code','below_global_warning','selectionKey',NULL,'thresholdPct','35')); END IF;
 position:=0;
 FOR item IN SELECT * FROM jsonb_array_elements(snapshot->'assemblySelections') LOOP
  position:=position+1;
  IF item->>'selectionKey'<>'selection:'||position::text OR (item->>'ordinal')::integer<>position THEN RETURN false; END IF;
  IF item->'extendedCostMinor'='null'::jsonb OR item->'extendedPriceMinor'='null'::jsonb OR (item->>'extendedPriceMinor')::numeric=0 THEN
   expected_warnings:=expected_warnings||jsonb_build_array(jsonb_build_object('code','assembly_margin_unknown','selectionKey',item->>'selectionKey','thresholdPct',NULL));
  ELSIF 100*((item->>'extendedPriceMinor')::numeric-(item->>'extendedCostMinor')::numeric)<28*(item->>'extendedPriceMinor')::numeric THEN
   expected_warnings:=expected_warnings||jsonb_build_array(jsonb_build_object('code','assembly_below_individual_warning','selectionKey',item->>'selectionKey','thresholdPct','28'));
  END IF;
 END LOOP;
 expected_evaluation:=jsonb_build_object('version','internal-approval-evaluation-v1','policyVersion',p->>'evaluatorVersion','policyHash',evaluation->>'policyHash','commercialChannel',p->>'commercialChannel','geoRiskClass',p->>'geoRiskClass','floorKind',floors->>'floorKind','effectiveFloorPct',floors->>'effectiveFloorPct','priceMinor',f->>'finalPriceMinor','costMinor',f->>'estimatedCostMinor','profitMinor',(price-cost)::text,'passed',true,'violations','[]'::jsonb,'warnings',expected_warnings);
 RETURN evaluation=expected_evaluation;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.internal_estimate_export_valid_manifest_v1(manifest jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  ctx jsonb; auth jsonb; val jsonb; rec jsonb; rep jsonb; issues jsonb; line_keys jsonb;
  ready boolean; principal text; rule_totals text; rule_vstate text; rule_rstate text;
  approved_nn boolean; exported_nn boolean; expected_diff numeric;
  seen_keys jsonb; i integer; key text; row_item jsonb; rows jsonb; expected_filename text;
  format text; details jsonb;
BEGIN
  IF jsonb_typeof(manifest) <> 'object' THEN RETURN false; END IF;
  IF manifest ?& ARRAY['version','format','attemptKind','outcome','exportId','context','authority','checkedAt','lineKeys','validation','representation'] IS NOT TRUE
     OR (SELECT count(*) FROM jsonb_object_keys(manifest)) <> 11 THEN RETURN false; END IF;
  -- Every comparison below against a text literal uses IS DISTINCT FROM (never a
  -- bare <>) and every NOT IN is guarded by an explicit IS NULL check first — a
  -- bare `x <> 'literal'` or `x NOT IN (...)` evaluates to SQL UNKNOWN (neither true
  -- nor false) when x is NULL (including when the JSON value at that key is JSON
  -- null, since ->>'' on JSON null yields SQL NULL), and a PL/pgSQL `IF <UNKNOWN>`
  -- is treated as false — it SKIPS the RETURN false and silently falls through,
  -- which is exactly how JSON/SQL null bypassed every one of these checks before.
  IF manifest->>'version' IS DISTINCT FROM 'internal-estimate-export-v1' THEN RETURN false; END IF;
  format := manifest->>'format';
  IF format IS NULL OR format NOT IN ('pdf','json','printable','csv_jobtread') THEN RETURN false; END IF;
  IF manifest->>'attemptKind' IS NULL OR manifest->>'attemptKind' NOT IN ('preflight','delivery') THEN RETURN false; END IF;
  IF manifest->>'outcome' IS DISTINCT FROM 'ready' AND manifest->>'outcome' IS DISTINCT FROM 'blocked' THEN RETURN false; END IF;
  ready := manifest->>'outcome' = 'ready';

  ctx := manifest->'context'; auth := manifest->'authority'; val := manifest->'validation';
  rec := val->'reconciliation'; rep := manifest->'representation'; line_keys := manifest->'lineKeys'; issues := val->'issues';

  -- context: 6 keys, UUID grammar, clientId nullable here (the XNOR rule below decides).
  IF ctx ?& ARRAY['tenantId','projectId','clientId','estimateDraftId','estimateVersion','requestedBy'] IS NOT TRUE
     OR (SELECT count(*) FROM jsonb_object_keys(ctx)) <> 6 THEN RETURN false; END IF;
  IF NOT public.internal_approval_matches_v1(ctx->'tenantId', jsonb_build_object('type','uuid'))
     OR NOT public.internal_approval_matches_v1(ctx->'projectId', jsonb_build_object('type','uuid'))
     OR NOT public.internal_approval_matches_v1(ctx->'clientId', jsonb_build_object('type','uuid','nullable',true))
     OR NOT public.internal_approval_matches_v1(ctx->'estimateDraftId', jsonb_build_object('type','uuid'))
     OR NOT public.internal_approval_matches_v1(ctx->'estimateVersion', jsonb_build_object('type','integer','min',1,'max',2147483647))
     OR NOT public.internal_approval_matches_v1(ctx->'requestedBy', jsonb_build_object('type','uuid'))
  THEN RETURN false; END IF;

  -- authority: NULL or exactly {approvalId,snapshotId,contentHash}.
  IF auth <> 'null'::jsonb THEN
    IF jsonb_typeof(auth) <> 'object' OR auth ?& ARRAY['approvalId','snapshotId','contentHash'] IS NOT TRUE
       OR (SELECT count(*) FROM jsonb_object_keys(auth)) <> 3
       OR NOT public.internal_approval_matches_v1(auth->'approvalId', jsonb_build_object('type','uuid'))
       OR NOT public.internal_approval_matches_v1(auth->'snapshotId', jsonb_build_object('type','uuid'))
       OR NOT public.internal_approval_matches_v1(auth->'contentHash', jsonb_build_object('type','hash'))
    THEN RETURN false; END IF;
  END IF;

  IF NOT public.internal_approval_matches_v1(manifest->'checkedAt', jsonb_build_object('type','timestamp')) THEN RETURN false; END IF;
  IF NOT public.internal_approval_matches_v1(manifest->'exportId', jsonb_build_object('type','uuid')) THEN RETURN false; END IF;

  -- lineKeys: array of LineKey, <=1000, distinct, exactly line:1..N in order.
  IF jsonb_typeof(line_keys) <> 'array' OR jsonb_array_length(line_keys) > 1000 THEN RETURN false; END IF;
  seen_keys := '[]'::jsonb;
  FOR i IN 0..jsonb_array_length(line_keys)-1 LOOP
    -- V5 fix (MICHAEL-A1-EXPORT-PHYSICAL-V4-QA-AND-COMPLETION.md §3 review item:
    -- "null lineKeys array elements"): a JSON null (or any object/array) element
    -- makes `->>` return SQL NULL, and `NULL !~ regex` is SQL UNKNOWN, not TRUE —
    -- the same three-valued-logic bug class fixed elsewhere in this migration.
    -- An explicit typeof check closes it before any text comparison is attempted.
    IF jsonb_typeof(line_keys->i) IS DISTINCT FROM 'string' THEN RETURN false; END IF;
    key := line_keys->>i;
    IF key !~ '^line:([1-9][0-9]{0,2}|1000)$' OR substring(key FROM 6)::integer <> i+1 THEN RETURN false; END IF;
    IF seen_keys @> jsonb_build_array(key) THEN RETURN false; END IF;
    seen_keys := seen_keys || jsonb_build_array(key);
  END LOOP;

  -- validation envelope shape.
  IF val ?& ARRAY['version','state','issues','reconciliation'] IS NOT TRUE OR (SELECT count(*) FROM jsonb_object_keys(val)) <> 4 THEN RETURN false; END IF;
  IF val->>'version' IS DISTINCT FROM 'internal-estimate-export-validation-v1' THEN RETURN false; END IF;
  IF val->>'state' IS NULL OR val->>'state' NOT IN ('not_evaluated','valid','invalid') THEN RETURN false; END IF;
  IF jsonb_typeof(issues) <> 'array' OR jsonb_array_length(issues) > 4002 THEN RETURN false; END IF;
  FOR i IN 0..jsonb_array_length(issues)-1 LOOP
    row_item := issues->i;
    IF row_item ?& ARRAY['code','lineKey','field'] IS NOT TRUE OR (SELECT count(*) FROM jsonb_object_keys(row_item)) <> 3 THEN RETURN false; END IF;
    IF public.a1_export_issue_class_rank_v1(row_item->>'code') IS NULL THEN RETURN false; END IF;
    -- V5 fix (MICHAEL-A1-EXPORT-PHYSICAL-V4-QA-AND-COMPLETION.md §3 review item:
    -- "issues.lineKey uses a generic code matcher"): A1-EXPORT-DATA-CONTRACT.md
    -- line 44 defines LineKey as the closed `line:<ordinal>` grammar, the SAME
    -- regex already used for the top-level lineKeys array a few lines above —
    -- the generic 'code' shape (any 1..128-char trimmed string) accepted values
    -- like "banana" or "line:0" that could never be a real LineKey. The contract
    -- (line 196) also requires a present lineKey to exist in the snapshot, but
    -- that cross-reference needs a live table read this function intentionally
    -- never does (it is a pure, closed grammar validator, per its header) — it
    -- is also unreachable from manifest JSON alone: ready manifests always carry
    -- zero issues (line 347) and blocked manifests always carry an empty
    -- lineKeys array (line 351), so there is never a manifest-local lineKeys
    -- array to cross-check a blocked row's issue against. That half of the rule
    -- belongs to a different layer (an application/trigger check against the
    -- real snapshot), not this grammar function; only the FORMAT half is fixed
    -- here.
    IF row_item->'lineKey' <> 'null'::jsonb AND (jsonb_typeof(row_item->'lineKey') IS DISTINCT FROM 'string' OR (row_item->>'lineKey') !~ '^line:([1-9][0-9]{0,2}|1000)$') THEN RETURN false; END IF;
    IF row_item->'field' <> 'null'::jsonb AND ((row_item->>'field') IS NULL OR (row_item->>'field') NOT IN ('identity','approval','source','version','currency','lines','quantity','unit',
      'unitCost','unitPrice','lineCost','linePrice','costType','taxable','costCode','discount','format','bytes','renderer')) THEN RETURN false; END IF;
  END LOOP;
  IF NOT public.a1_export_issue_order_valid_v1(issues) THEN RETURN false; END IF;

  IF rec ?& ARRAY['state','approvedTotalMinor','exportedTotalMinor','differenceMinor','estimatedCostMinor'] IS NOT TRUE
     OR (SELECT count(*) FROM jsonb_object_keys(rec)) <> 5 THEN RETURN false; END IF;
  IF rec->>'state' IS NULL OR rec->>'state' NOT IN ('not_evaluated','matched','mismatch','unrepresentable') THEN RETURN false; END IF;
  IF rec->'approvedTotalMinor' <> 'null'::jsonb AND NOT public.internal_approval_matches_v1(rec->'approvedTotalMinor', jsonb_build_object('type','minor')) THEN RETURN false; END IF;
  IF rec->'exportedTotalMinor' <> 'null'::jsonb AND NOT public.internal_approval_matches_v1(rec->'exportedTotalMinor', jsonb_build_object('type','minor')) THEN RETURN false; END IF;
  IF rec->'estimatedCostMinor' <> 'null'::jsonb AND NOT public.internal_approval_matches_v1(rec->'estimatedCostMinor', jsonb_build_object('type','minor')) THEN RETURN false; END IF;
  IF rec->'differenceMinor' <> 'null'::jsonb AND NOT public.internal_approval_matches_v1(rec->'differenceMinor', jsonb_build_object('type','signed_minor')) THEN RETURN false; END IF;

  -- §4 top-level ready/blocked coherence.
  IF ready THEN
    IF rep = 'null'::jsonb OR jsonb_array_length(line_keys) < 1 OR jsonb_array_length(issues) <> 0 OR auth = 'null'::jsonb THEN RETURN false; END IF;
    IF rep->>'format' IS DISTINCT FROM format THEN RETURN false; END IF;
    principal := NULL; rule_totals := 'full'; rule_vstate := 'valid'; rule_rstate := 'matched';
  ELSE
    IF rep <> 'null'::jsonb OR jsonb_array_length(line_keys) <> 0 OR jsonb_array_length(issues) < 1 THEN RETURN false; END IF;
    principal := issues->0->>'code';
    rule_totals := public.a1_export_issue_totals_class_v1(principal);
    rule_vstate := public.a1_export_issue_validation_state_v1(principal);
    rule_rstate := public.a1_export_issue_reconciliation_state_v1(principal);
  END IF;

  IF val->>'state' IS DISTINCT FROM rule_vstate THEN RETURN false; END IF;
  IF rec->>'state' IS DISTINCT FROM rule_rstate THEN RETURN false; END IF;
  approved_nn := rule_totals <> 'none'; exported_nn := rule_totals = 'full';
  IF (rec->'approvedTotalMinor' <> 'null'::jsonb) IS DISTINCT FROM approved_nn THEN RETURN false; END IF;
  IF (rec->'estimatedCostMinor' <> 'null'::jsonb) IS DISTINCT FROM approved_nn THEN RETURN false; END IF;
  IF (rec->'exportedTotalMinor' <> 'null'::jsonb) IS DISTINCT FROM exported_nn THEN RETURN false; END IF;
  IF (rec->'differenceMinor' <> 'null'::jsonb) IS DISTINCT FROM exported_nn THEN RETURN false; END IF;
  IF exported_nn THEN
    expected_diff := (rec->>'exportedTotalMinor')::numeric - (rec->>'approvedTotalMinor')::numeric;
    IF expected_diff IS DISTINCT FROM (rec->>'differenceMinor')::numeric THEN RETURN false; END IF;
    IF principal = 'EXPORT_RECONCILIATION_MISMATCH' AND (rec->>'differenceMinor')::numeric = 0 THEN RETURN false; END IF;
    IF ready AND ((rec->>'approvedTotalMinor') IS DISTINCT FROM (rec->>'exportedTotalMinor') OR (rec->>'approvedTotalMinor')::numeric <= 0) THEN RETURN false; END IF;
  END IF;
  IF ready THEN
    IF auth = 'null'::jsonb THEN RETURN false; END IF;
  ELSE
    IF (auth = 'null'::jsonb) IS DISTINCT FROM public.a1_export_authority_null_required_v1(principal) THEN RETURN false; END IF;
  END IF;

  -- §3.2 client XNOR; §5.4 CSV-exclusive codes never justify a non-CSV block.
  IF (ctx->'clientId' = 'null'::jsonb) IS DISTINCT FROM (NOT ready AND public.a1_export_client_null_required_v1(principal)) THEN RETURN false; END IF;
  IF format <> 'csv_jobtread' THEN
    FOR i IN 0..jsonb_array_length(issues)-1 LOOP
      IF public.a1_export_csv_exclusive_code_v1(issues->i->>'code') THEN RETURN false; END IF;
    END LOOP;
  END IF;

  IF rep = 'null'::jsonb THEN RETURN true; END IF;

  -- representation common fields + generatedAt<=checkedAt + generatedBy=requestedBy
  -- + filename encodes THIS manifest's own draftId/exportId + per-format mime/renderer.
  IF rep ?& ARRAY['format','rendererVersion','generatedAt','generatedBy','filename','mimeType','encoding','artifactHash','byteLength','details'] IS NOT TRUE
     OR (SELECT count(*) FROM jsonb_object_keys(rep)) <> 10 THEN RETURN false; END IF;
  IF NOT public.internal_approval_matches_v1(rep->'generatedAt', jsonb_build_object('type','timestamp'))
     OR (rep->>'generatedAt') > (manifest->>'checkedAt') THEN RETURN false; END IF;
  IF rep->>'generatedBy' IS DISTINCT FROM ctx->>'requestedBy' THEN RETURN false; END IF;
  IF NOT public.internal_approval_matches_v1(rep->'artifactHash', jsonb_build_object('type','hash')) THEN RETURN false; END IF;
  IF NOT public.internal_approval_matches_v1(rep->'byteLength', jsonb_build_object('type','integer','min',1,'max',10485760)) THEN RETURN false; END IF;
  expected_filename := 'EST-' || (ctx->>'estimateDraftId') || '-' || (manifest->>'exportId') || '.' ||
    CASE format WHEN 'pdf' THEN 'pdf' WHEN 'json' THEN 'json' WHEN 'printable' THEN 'html' ELSE 'csv' END;
  IF rep->>'filename' IS DISTINCT FROM expected_filename THEN RETURN false; END IF;
  details := rep->'details';
  IF format = 'pdf' THEN
    IF rep->>'rendererVersion' IS DISTINCT FROM 'internal-estimate-pdf-v1' OR rep->>'mimeType' IS DISTINCT FROM 'application/pdf' OR rep->>'encoding' IS DISTINCT FROM 'base64' THEN RETURN false; END IF;
    IF details ?& ARRAY['layoutVersion','pageCount'] IS NOT TRUE OR (SELECT count(*) FROM jsonb_object_keys(details)) <> 2
       OR details->>'layoutVersion' IS DISTINCT FROM 'internal-estimate-summary-v1'
       OR NOT public.internal_approval_matches_v1(details->'pageCount', jsonb_build_object('type','integer','min',1,'max',10000))
    THEN RETURN false; END IF;
  ELSIF format = 'json' THEN
    IF rep->>'rendererVersion' IS DISTINCT FROM 'internal-estimate-json-v1' OR rep->>'mimeType' IS DISTINCT FROM 'application/json' OR rep->>'encoding' IS DISTINCT FROM 'utf8' THEN RETURN false; END IF;
    IF details ?& ARRAY['documentVersion','serialization'] IS NOT TRUE OR (SELECT count(*) FROM jsonb_object_keys(details)) <> 2
       OR details->>'documentVersion' IS DISTINCT FROM 'internal-estimate-document-v1' OR details->>'serialization' IS DISTINCT FROM 'canonical-json-utf8-v1'
    THEN RETURN false; END IF;
  ELSIF format = 'printable' THEN
    IF rep->>'rendererVersion' IS DISTINCT FROM 'internal-estimate-printable-v1' OR rep->>'mimeType' IS DISTINCT FROM 'text/html' OR rep->>'encoding' IS DISTINCT FROM 'utf8' THEN RETURN false; END IF;
    IF details ?& ARRAY['templateVersion','escaping','sandbox'] IS NOT TRUE OR (SELECT count(*) FROM jsonb_object_keys(details)) <> 3
       OR details->>'templateVersion' IS DISTINCT FROM 'internal-estimate-summary-v1' OR details->>'escaping' IS DISTINCT FROM 'html-text-attribute-v1' OR details->>'sandbox' IS DISTINCT FROM 'no-scripts-no-network-v1'
    THEN RETURN false; END IF;
  ELSE -- csv_jobtread
    IF rep->>'rendererVersion' IS DISTINCT FROM 'internal-estimate-jobtread-csv-v1' OR rep->>'mimeType' IS DISTINCT FROM 'text/csv' OR rep->>'encoding' IS DISTINCT FROM 'utf8' THEN RETURN false; END IF;
    IF details ?& ARRAY['contractVersion','classificationVersion','headers','delimiter','lineEnding','utf8Bom','rows'] IS NOT TRUE
       OR (SELECT count(*) FROM jsonb_object_keys(details)) <> 7
       OR details->>'contractVersion' IS DISTINCT FROM 'jobtread-budget-csv-a1-v1'
       OR details->>'classificationVersion' IS DISTINCT FROM 'jobtread-s20.1-classification-h1-8550e842-v1'
       OR details->'headers' <> '["Cost Group Name","Cost Item Name","Description","Quantity","Unit","Unit Cost","Unit Price","Cost Type","Taxable"]'::jsonb
       OR details->>'delimiter' IS DISTINCT FROM ',' OR details->>'lineEnding' IS DISTINCT FROM 'CRLF' OR details->'utf8Bom' <> 'false'::jsonb
    THEN RETURN false; END IF;
    rows := details->'rows';
    IF jsonb_typeof(rows) <> 'array' OR jsonb_array_length(rows) < 1 OR jsonb_array_length(rows) > 1000
       OR jsonb_array_length(rows) <> jsonb_array_length(line_keys) THEN RETURN false; END IF;
    FOR i IN 0..jsonb_array_length(rows)-1 LOOP
      row_item := rows->i;
      IF row_item ?& ARRAY['lineKey','ordinal','costGroupName','costItemName','description','quantity','unit','unitCost','unitPrice',
        'costType','taxable','costCode','assemblyId','lineCostMinor','linePriceMinor','costTypeSource','unitSource','costCodeSource'] IS NOT TRUE
        OR (SELECT count(*) FROM jsonb_object_keys(row_item)) <> 18 THEN RETURN false; END IF;
      IF row_item->>'lineKey' IS DISTINCT FROM 'line:' || (i+1)::text THEN RETURN false; END IF;
      -- V5 fix (MICHAEL-A1-EXPORT-PHYSICAL-V4-QA-AND-COMPLETION.md §3 review item:
      -- "CSV ordinal JSON type"): A1-EXPORT-DATA-CONTRACT.md line 256 requires
      -- ordinal to be an actual integer, but `->>` stringifies whatever JSON type
      -- is there before the ::integer cast, so a JSON STRING "1" (never a real
      -- integer) passed this check undetected. jsonb_typeof is checked first.
      IF jsonb_typeof(row_item->'ordinal') IS DISTINCT FROM 'number' OR (row_item->>'ordinal')::integer IS DISTINCT FROM i+1 THEN RETURN false; END IF;
      IF NOT public.internal_approval_matches_v1(row_item->'costGroupName', jsonb_build_object('type','label'))
         OR NOT public.internal_approval_matches_v1(row_item->'costItemName', jsonb_build_object('type','label'))
         OR NOT public.internal_approval_matches_v1(row_item->'description', jsonb_build_object('type','text'))
         OR NOT public.internal_approval_matches_v1(row_item->'quantity', jsonb_build_object('type','positive_decimal'))
         OR NOT public.internal_approval_matches_v1(row_item->'lineCostMinor', jsonb_build_object('type','minor'))
         OR NOT public.internal_approval_matches_v1(row_item->'linePriceMinor', jsonb_build_object('type','minor'))
         OR NOT public.internal_approval_matches_v1(row_item->'assemblyId', jsonb_build_object('type','uuid','nullable',true))
      THEN RETURN false; END IF;
      -- costGroupName/costItemName/description must ALREADY be canonical (no silent
      -- trim/CRLF repair of recorded evidence) — the matcher above only checks
      -- bounds/Unicode; re-derive the trimmed form and require it to be a no-op.
      IF public.internal_approval_trim_v1(replace(replace(row_item->>'costGroupName',E'\r\n',E'\n'),E'\r',E'\n')) IS DISTINCT FROM row_item->>'costGroupName'
         OR public.internal_approval_trim_v1(replace(replace(row_item->>'costItemName',E'\r\n',E'\n'),E'\r',E'\n')) IS DISTINCT FROM row_item->>'costItemName'
         OR replace(replace(row_item->>'description',E'\r\n',E'\n'),E'\r',E'\n') IS DISTINCT FROM row_item->>'description'
      THEN RETURN false; END IF;
      IF row_item->>'unit' IS NULL OR row_item->>'unit' NOT IN ('Each','Hours','Linear Feet','Lump Sum','Square Feet','Squares','Tons','Cubic Yards','Pounds','Bags','Boxes','Bundles','Gallons','Pieces','Rolls','Sets','Sheets')
      THEN RETURN false; END IF;
      IF row_item->>'costType' IS NULL OR row_item->>'costType' NOT IN ('Allowance','Equipment / Rental','Labor','Materials','Other','Permits / Fees','Subcontractor') THEN RETURN false; END IF;
      IF jsonb_typeof(row_item->'taxable') <> 'boolean' THEN RETURN false; END IF;
      IF row_item->>'costTypeSource' IS DISTINCT FROM 'classifyCostType_v1' THEN RETURN false; END IF;
      IF row_item->>'unitSource' IS NULL OR row_item->>'unitSource' NOT IN ('stored_canonical','normalizeUnit_v1') THEN RETURN false; END IF;
      -- Ready CSV never carries unreviewed classification: 'unknown' is always
      -- refused, which also makes a null costCode unreachable (the only source
      -- value that would have permitted one).
      IF row_item->>'costCodeSource' IS NULL OR row_item->>'costCodeSource' NOT IN ('stored','inferCostCode_v1') OR row_item->'costCode' = 'null'::jsonb THEN RETURN false; END IF;
      -- V5 fix (MICHAEL-A1-EXPORT-PHYSICAL-V4-QA-AND-COMPLETION.md §3 review item:
      -- "CSV unitCost/unitPrice JSON type"): A1-EXPORT-DATA-CONTRACT.md line 256
      -- requires these as fixed-two-decimal STRINGS specifically (so the exact
      -- digits round-trip, never a float) — but jsonb preserves a numeric
      -- literal's original digit text, so a JSON NUMBER 5.00 serializes via `->>`
      -- to the same "5.00" the regex below accepts, letting the wrong JSON type
      -- through unnoticed. jsonb_typeof is checked first.
      IF jsonb_typeof(row_item->'unitCost') IS DISTINCT FROM 'string' OR jsonb_typeof(row_item->'unitPrice') IS DISTINCT FROM 'string' THEN RETURN false; END IF;
      IF row_item->>'unitCost' IS NULL OR row_item->>'unitPrice' IS NULL
         OR row_item->>'unitCost' !~ '^(0|[1-9][0-9]{0,13})\.[0-9]{2}$' OR row_item->>'unitPrice' !~ '^(0|[1-9][0-9]{0,13})\.[0-9]{2}$' THEN RETURN false; END IF;
      -- §6.4/§7: the represented quantity*rate must reconcile to the represented
      -- total — the snapshot never cross-validates this on its own.
      IF public.a1_export_exact_amount_minor_v1(row_item->>'quantity', row_item->>'unitCost') <> (row_item->>'lineCostMinor')::numeric
         OR public.a1_export_exact_amount_minor_v1(row_item->>'quantity', row_item->>'unitPrice') <> (row_item->>'linePriceMinor')::numeric
      THEN RETURN false; END IF;
    END LOOP;
  END IF;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR invalid_datetime_format OR numeric_value_out_of_range OR division_by_zero THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.jobtread_export_a1_check_final_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  d public.estimate_drafts;
  p public.projects;
  a public.estimate_internal_approvals;
  s public.estimate_internal_approval_snapshots;
  is_insert boolean;
  is_first_download boolean;
  is_ready boolean;
  csv_row jsonb;
  csv_line jsonb;
  csv_class jsonb;
  csv_sum_cost numeric;
  csv_sum_price numeric;
BEGIN
  is_insert := TG_OP = 'INSERT';
  is_first_download := TG_OP = 'UPDATE' AND OLD.status = 'approved_for_download' AND NEW.status = 'downloaded';
  -- The norm names exactly two moments (A1-EXPORT-DATA-CONTRACT.md §6, lines 276-283):
  -- the first commit and EACH first download projection. A later no-op/idempotent
  -- UPDATE (OLD.status already 'downloaded') is neither — re-deciding it would wrongly
  -- punish an identical retry for a revocation that happened after the real decision
  -- this row already recorded.
  IF NOT (is_insert OR is_first_download) THEN RETURN NULL; END IF;

  is_ready := NEW.manifest->>'outcome' = 'ready';

  -- §6 item 1: basic context is checked for EVERY applicable row, even authority-NULL
  -- (no-decision) ones — real draft lock FIRST, FOR UPDATE (the SAME mode 0007's own
  -- internal_approval_check_final_v1 takes on estimate_drafts — NOT FOR KEY SHARE,
  -- which 0007 uses only for a lighter parent-context read elsewhere), then re-read
  -- before deciding anything, never trusting a lock-free read the caller might hold.
  SELECT * INTO d FROM public.estimate_drafts WHERE id = NEW.estimate_draft_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'A1_EXPORT_DRAFT_MISSING' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_draft_missing',TABLE='jobtread_exports';
  END IF;
  IF d.tenant_id IS DISTINCT FROM NEW.tenant_id OR d.project_id IS DISTINCT FROM NEW.project_id THEN
    RAISE EXCEPTION 'A1_EXPORT_DRAFT_CONTEXT_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_draft_context',TABLE='jobtread_exports';
  END IF;
  IF (NEW.manifest->'context'->>'estimateVersion')::integer IS DISTINCT FROM d.version THEN
    RAISE EXCEPTION 'A1_EXPORT_DRAFT_VERSION_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_draft_version',TABLE='jobtread_exports';
  END IF;
  -- clientId present must match the draft's real client; NULL is permitted only in
  -- the blocks the structural CHECK already restricts to ESTIMATE_CLIENT_MISSING/
  -- ESTIMATE_CLIENT_CONTEXT_MISMATCH.
  IF NEW.client_id IS NOT NULL AND NEW.client_id IS DISTINCT FROM d.client_id THEN
    RAISE EXCEPTION 'A1_EXPORT_CLIENT_CONTEXT_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_client_context',TABLE='jobtread_exports';
  END IF;
  -- V5 fix (MICHAEL-A1-EXPORT-PHYSICAL-V4-QA-AND-COMPLETION.md §3 review item:
  -- "client-match-to-project, not just client-match-to-draft"):
  -- A1-EXPORT-DATA-CONTRACT.md §3.2 is explicit — "client_id, quando não NULL, é
  -- igual ao cliente do draft E do projeto no tenant" (equal to the client of
  -- the draft AND of the project, not the draft alone). The check above only
  -- ever compared against the draft's own client_id; a project whose own
  -- client_id disagreed with the draft's (a real, representable inconsistency —
  -- a project can be reassigned a different client than a draft created under
  -- its earlier one) would pass undetected. The project's client is now also
  -- checked, independently of the draft's.
  SELECT * INTO p FROM public.projects WHERE id = NEW.project_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'A1_EXPORT_PROJECT_MISSING' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_project_missing',TABLE='jobtread_exports';
  END IF;
  IF NEW.client_id IS NOT NULL AND NEW.client_id IS DISTINCT FROM p.client_id THEN
    RAISE EXCEPTION 'A1_EXPORT_CLIENT_CONTEXT_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_client_context',TABLE='jobtread_exports';
  END IF;

  -- V7 fix (MICHAEL-A1-EXPORT-PHYSICAL-V6-QA-AND-COMPLETION.md §1a):
  -- A1-EXPORT-DATA-CONTRACT.md §5.2 — "lineKey nullable e, se presente, deve
  -- existir no snapshot." With no usable decision (no authority), there is no
  -- snapshot to check existence against at all — a lexically well-formed
  -- LineKey like "line:999" is NOT evidence it refers to anything real, and
  -- must never be persisted as if it were. The pure grammar function
  -- (internal_estimate_export_valid_manifest_v1) only validates the FORMAT of
  -- issues[].lineKey (V5 fix) — it cannot check real-table existence by
  -- design (no table reads). This is the one place in the physical unit that
  -- legitimately can, and must, for the authority-NULL case.
  IF NEW.internal_approval_id IS NULL AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(NEW.manifest->'validation'->'issues') elem
    WHERE elem->'lineKey' IS DISTINCT FROM 'null'::jsonb
  ) THEN
    RAISE EXCEPTION 'A1_EXPORT_ISSUE_LINEKEY_UNVERIFIABLE' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_issue_linekey_unverifiable',TABLE='jobtread_exports';
  END IF;

  -- Authority-NULL rows (no real decision claimed) have nothing further to
  -- correspond against — already structurally required for exactly the six
  -- "no usable decision" issue codes.
  IF NEW.internal_approval_id IS NULL THEN RETURN NULL; END IF;

  -- §6 item 2: same approval/snapshot/hash (defense-in-depth alongside
  -- jte_a1_approval_fk/jte_a1_snapshot_hash_fk, which already enforce this
  -- declaratively — kept here since a plain FK can't express the manifest-vs-real-row
  -- comparisons this function needs anyway).
  SELECT * INTO a FROM public.estimate_internal_approvals WHERE id = NEW.internal_approval_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'A1_EXPORT_APPROVAL_MISSING' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_approval_missing',TABLE='jobtread_exports';
  END IF;
  SELECT * INTO s FROM public.estimate_internal_approval_snapshots WHERE id = a.snapshot_id;
  IF NOT FOUND OR NEW.internal_snapshot_id IS DISTINCT FROM a.snapshot_id THEN
    RAISE EXCEPTION 'A1_EXPORT_SNAPSHOT_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_snapshot_mismatch',TABLE='jobtread_exports';
  END IF;
  IF NEW.approved_content_hash IS DISTINCT FROM s.content_hash THEN
    RAISE EXCEPTION 'A1_EXPORT_HASH_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_hash_mismatch',TABLE='jobtread_exports';
  END IF;

  -- V7 fix (MICHAEL-A1-EXPORT-PHYSICAL-V6-QA-AND-COMPLETION.md §1a, known-
  -- authority half): with a real snapshot now loaded (`s`), every NON-NULL
  -- issues[].lineKey must actually belong to it — lexical validity (the V5
  -- format fix) is not evidence of belonging. Applies regardless of ready/
  -- blocked (harmless no-op for ready, which always has 0 issues by
  -- grammar) — covers a blocked-with-known-decision row (e.g. revoked/
  -- superseded) whose issue claims a line that never existed in that exact
  -- snapshot. The accepted TS engine (shared/internal-estimate-export-
  -- engine.ts:313) already includes issues in its own comparison set; this
  -- is the SQL side's matching real-table check, not a semantic change.
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(NEW.manifest->'validation'->'issues') elem
    WHERE elem->'lineKey' IS DISTINCT FROM 'null'::jsonb
      AND NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(s.snapshot_payload->'lines') line
        WHERE line->>'lineKey' = elem->>'lineKey'
      )
  ) THEN
    RAISE EXCEPTION 'A1_EXPORT_ISSUE_LINEKEY_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_issue_linekey_mismatch',TABLE='jobtread_exports';
  END IF;

  -- §6 item 4 (totals part): the pure engine compares approvedTotal/estimatedCost to
  -- the snapshot WHENEVER authority exists — including a blocked row with a known
  -- decision (e.g. INTERNAL_APPROVAL_REVOKED, whose totals class is "approvedOnly").
  -- This must NOT be gated on is_ready; we are already past the authority-NULL
  -- early-return, so internal_approval_id is guaranteed non-null here regardless of
  -- outcome.
  IF NEW.manifest->'validation'->'reconciliation'->>'approvedTotalMinor' IS DISTINCT FROM s.final_price_minor::text THEN
    RAISE EXCEPTION 'A1_EXPORT_APPROVED_TOTAL_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_approved_total_mismatch',TABLE='jobtread_exports';
  END IF;
  IF NEW.manifest->'validation'->'reconciliation'->>'estimatedCostMinor' IS DISTINCT FROM s.estimated_cost_minor::text THEN
    RAISE EXCEPTION 'A1_EXPORT_ESTIMATED_COST_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_estimated_cost_mismatch',TABLE='jobtread_exports';
  END IF;

  -- §6 item 3: vigency AT THIS EVENT — never at the manifest's own frozen checked_at,
  -- which is not a waiver. Only a 'ready' claim needs current authority; a blocked row
  -- whose own issue is INTERNAL_APPROVAL_REVOKED/ESTIMATE_SUPERSEDED is declaring that
  -- state as its reason, not hiding it. "Não disparar invalidação retroativa": the
  -- already-committed ROW is never touched by a later revocation (immutability above
  -- already guarantees that) — but EACH new projection (this INSERT, or this later
  -- first-download UPDATE) re-queries the core tables for itself, under the lock just
  -- taken on the draft.
  IF is_ready THEN
    -- V7 fix (MICHAEL-A1-EXPORT-PHYSICAL-V6-QA-AND-COMPLETION.md §1b): lineage/
    -- ancestry eligibility (0007's own accepted check — H1 identity by source OR
    -- relational link, bounded ancestry; a tampered source does not make history
    -- eligible) gates READY delivery specifically — it is NOT a generic validator
    -- of blocked evidence. A1-EXPORT-DATA-CONTRACT.md §6 requires vigency/
    -- eligibility only for ready; §§3.2/4/8 allow recording a block in the basic
    -- authorized context regardless of whether the draft would ever BE eligible
    -- (e.g. a historical_import-sourced draft blocked with
    -- HISTORICAL_AUTHORITY_NOT_AVAILABLE, or a client-missing draft blocked with
    -- ESTIMATE_CLIENT_MISSING — both real, legitimate blocked records this
    -- function must accept). Previously called unconditionally above, for EVERY
    -- applicable row including blocked ones — rejecting the very evidence that
    -- explains why the draft is ineligible. Moved here so it still rejects a
    -- READY claim from an ineligible-source/broken-ancestry draft (regression:
    -- the existing ready scenarios below and the real writers' own fixtures),
    -- while a blocked row no longer needs to pass an eligibility check it is
    -- explicitly declaring it does NOT meet.
    PERFORM public.internal_approval_check_lineage_v1(d.id);

    -- Most specific reason first: a real revocation row naming this exact approval,
    -- before the more general core-eligible-state check (which the same revocation
    -- also flips d.status for, per 0007's own guard — checking the specific table
    -- first gives a clearer diagnostic without changing what is ultimately rejected).
    IF EXISTS (SELECT 1 FROM public.estimate_internal_approval_revocations WHERE approval_id = a.id) THEN
      RAISE EXCEPTION 'A1_EXPORT_APPROVAL_REVOKED' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_approval_revoked',TABLE='jobtread_exports';
    END IF;
    IF d.superseded_by IS NOT NULL THEN
      RAISE EXCEPTION 'A1_EXPORT_DRAFT_SUPERSEDED' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_draft_superseded',TABLE='jobtread_exports';
    END IF;
    IF d.status IS DISTINCT FROM 'internally_approved' THEN
      RAISE EXCEPTION 'A1_EXPORT_DRAFT_NOT_ELIGIBLE' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_draft_not_eligible',TABLE='jobtread_exports';
    END IF;

    -- §6 item 4 (non-CSV part): exact lineKeys/row-count/order correspond to the
    -- real snapshot — not merely well-formed, actually equal to it. (Totals are
    -- checked above, unconditionally on authority presence, not gated here.)
    IF NEW.manifest->'lineKeys' IS DISTINCT FROM (
      SELECT jsonb_agg(line->>'lineKey' ORDER BY ord) FROM jsonb_array_elements(s.snapshot_payload->'lines') WITH ORDINALITY AS t(line, ord)
    ) THEN
      RAISE EXCEPTION 'A1_EXPORT_LINEKEYS_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_linekeys_mismatch',TABLE='jobtread_exports';
    END IF;

    -- CSV-specific exact correspondence (classification/provenance/taxation/rate/
    -- discount) — only when the representation IS CSV. Mirrors
    -- checkExportCsvRowAgainstLine/checkExportCsvAgainstSnapshot
    -- (shared/internal-estimate-export-engine.ts) against the REAL snapshot lines,
    -- not merely a well-formed row. rateExact uses the SAME exactTwoDecimal rule as
    -- the pure engine (a1_export_exact_two_decimal_v1 above) — a plain numeric
    -- comparison is NOT equivalent (a snapshot value with more than 2 fraction
    -- digits must be rejected even when numerically equal to the candidate).
    IF NEW.manifest->'representation'->>'format' = 'csv_jobtread' THEN
      csv_sum_cost := 0; csv_sum_price := 0;
      FOR csv_row IN SELECT value FROM jsonb_array_elements(NEW.manifest->'representation'->'details'->'rows')
      LOOP
        SELECT value INTO csv_line FROM jsonb_array_elements(s.snapshot_payload->'lines') AS value
          WHERE value->>'lineKey' = csv_row->>'lineKey';
        IF csv_line IS NULL THEN
          RAISE EXCEPTION 'A1_EXPORT_CSV_LINE_MISSING' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_csv_line_missing',TABLE='jobtread_exports';
        END IF;
        IF csv_line->>'costGroupName' IS DISTINCT FROM csv_row->>'costGroupName'
           OR csv_line->>'costItemName' IS DISTINCT FROM csv_row->>'costItemName'
           OR COALESCE(csv_line->>'description','') IS DISTINCT FROM csv_row->>'description'
           OR csv_line->>'quantity' IS DISTINCT FROM csv_row->>'quantity'
           OR csv_line->>'assemblyId' IS DISTINCT FROM csv_row->>'assemblyId'
           OR (csv_line->>'taxable')::boolean IS DISTINCT FROM (csv_row->>'taxable')::boolean
           OR csv_line->>'lineTotalCostMinor' IS DISTINCT FROM csv_row->>'lineCostMinor'
           OR csv_line->>'lineTotalPriceMinor' IS DISTINCT FROM csv_row->>'linePriceMinor'
        THEN
          RAISE EXCEPTION 'A1_EXPORT_CSV_IDENTITY_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_csv_identity_mismatch',TABLE='jobtread_exports';
        END IF;
        csv_class := csv_line->'csvClassification';
        IF csv_class IS NULL OR csv_class = 'null'::jsonb
           OR csv_class->>'costType' IS DISTINCT FROM csv_row->>'costType'
           OR csv_class->>'normalizedUnit' IS DISTINCT FROM csv_row->>'unit'
           OR csv_class->>'costCode' IS DISTINCT FROM csv_row->>'costCode'
           OR csv_class->>'unitSource' IS DISTINCT FROM csv_row->>'unitSource'
           OR csv_class->>'costCodeSource' IS DISTINCT FROM csv_row->>'costCodeSource'
        THEN
          RAISE EXCEPTION 'A1_EXPORT_CSV_CLASSIFICATION_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_csv_classification_mismatch',TABLE='jobtread_exports';
        END IF;
        IF NOT public.a1_export_exact_two_decimal_v1(csv_line->>'unitCostSnapshot', csv_row->>'unitCost')
           OR NOT public.a1_export_exact_two_decimal_v1(csv_line->>'unitPriceSnapshot', csv_row->>'unitPrice')
        THEN
          RAISE EXCEPTION 'A1_EXPORT_CSV_RATE_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_csv_rate_mismatch',TABLE='jobtread_exports';
        END IF;
        -- Exact quantity×rate extension, half-away-from-zero at the cent — reusing the
        -- SAME a1_export_exact_amount_minor_v1 the structural CHECK above already uses
        -- (itself the SQL mirror of computeExactAmountMinor), not a second
        -- reimplementation of the same rule.
        IF public.a1_export_exact_amount_minor_v1(csv_row->>'quantity', csv_row->>'unitCost') IS DISTINCT FROM (csv_row->>'lineCostMinor')::numeric
           OR public.a1_export_exact_amount_minor_v1(csv_row->>'quantity', csv_row->>'unitPrice') IS DISTINCT FROM (csv_row->>'linePriceMinor')::numeric
        THEN
          RAISE EXCEPTION 'A1_EXPORT_CSV_AMOUNT_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_csv_amount_mismatch',TABLE='jobtread_exports';
        END IF;
        csv_sum_cost := csv_sum_cost + (csv_row->>'lineCostMinor')::numeric;
        csv_sum_price := csv_sum_price + (csv_row->>'linePriceMinor')::numeric;
      END LOOP;
      IF csv_sum_cost IS DISTINCT FROM (NEW.manifest->'validation'->'reconciliation'->>'estimatedCostMinor')::numeric THEN
        RAISE EXCEPTION 'A1_EXPORT_CSV_SUM_COST_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_csv_sum_cost_mismatch',TABLE='jobtread_exports';
      END IF;
      IF csv_sum_price IS DISTINCT FROM (NEW.manifest->'validation'->'reconciliation'->>'exportedTotalMinor')::numeric THEN
        RAISE EXCEPTION 'A1_EXPORT_CSV_SUM_PRICE_MISMATCH' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_csv_sum_price_mismatch',TABLE='jobtread_exports';
      END IF;
      -- CSV's 9 columns cannot represent a discount; a ready CSV export must come
      -- from a snapshot with none to hide.
      IF (s.snapshot_payload->'financials'->>'discountApplied')::boolean IS TRUE
         OR (s.snapshot_payload->'financials'->>'discountMinor') IS DISTINCT FROM '0' THEN
        RAISE EXCEPTION 'A1_EXPORT_CSV_DISCOUNT_UNREPRESENTABLE' USING ERRCODE='23514',CONSTRAINT='jte_a1_export_csv_discount_unrepresentable',TABLE='jobtread_exports';
      END IF;
    END IF;
  END IF;

  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jobtread_export_a1_immutability_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  is_legal_download boolean;
  gen_cols text[];
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.artifact_contract_version IS NOT NULL THEN
      RAISE EXCEPTION 'A1 export evidence cannot be deleted, including by cascade.'
        USING ERRCODE = '23514', CONSTRAINT = 'jte_a1_delete_forbidden', TABLE = 'jobtread_exports';
    END IF;
    RETURN OLD;
  END IF;

  -- UPDATE. A legacy row (OLD marker NULL) may never be promoted to A1 by UPDATE.
  IF OLD.artifact_contract_version IS NULL THEN
    IF NEW.artifact_contract_version IS NOT NULL THEN
      RAISE EXCEPTION 'A legacy row cannot be promoted to an A1 record by UPDATE.'
        USING ERRCODE = '23514', CONSTRAINT = 'jte_a1_legacy_promotion_forbidden', TABLE = 'jobtread_exports';
    END IF;
    RETURN NEW; -- legacy row, legacy UPDATE path — unchanged behavior.
  END IF;

  -- Generated columns (a1_estimate_draft_id/a1_requested_by/a1_downloaded_by) are NOT
  -- yet recomputed on NEW inside a BEFORE ROW trigger — Postgres fills them in only
  -- after the BEFORE trigger chain returns — so NEW always carries them as NULL here
  -- regardless of the real, persisted value OLD shows. Every to_jsonb comparison in
  -- this function must exclude all three or it would see a spurious "change" on
  -- every single UPDATE of an A1 row, including true no-ops. Their real underlying
  -- base columns (estimate_draft_id, requested_by, downloaded_by, artifact_contract_version)
  -- are ordinary stored columns and remain fully compared, so this costs no protection.
  gen_cols := ARRAY['a1_estimate_draft_id','a1_requested_by','a1_downloaded_by'];

  -- Exact no-op is always permitted (to_jsonb comparison catches it below too,
  -- but checked explicitly first for a clearer exception message otherwise).
  IF to_jsonb(NEW) - gen_cols = to_jsonb(OLD) - gen_cols THEN RETURN NEW; END IF;

  is_legal_download :=
    OLD.status = 'approved_for_download' AND NEW.status = 'downloaded'
    AND OLD.downloaded_by IS NULL AND OLD.downloaded_at IS NULL
    AND NEW.downloaded_by IS NOT NULL AND NEW.downloaded_at IS NOT NULL
    AND NEW.updated_at = NEW.downloaded_at
    AND date_trunc('milliseconds', NEW.downloaded_at) = NEW.downloaded_at;

  IF is_legal_download THEN
    -- Every OTHER column must be unchanged in this same transition.
    IF to_jsonb(NEW) - gen_cols - ARRAY['status','downloadedBy','downloadedAt','updatedAt','downloaded_by','downloaded_at','updated_at']
       IS DISTINCT FROM to_jsonb(OLD) - gen_cols - ARRAY['status','downloadedBy','downloadedAt','updatedAt','downloaded_by','downloaded_at','updated_at']
    THEN
      RAISE EXCEPTION 'The only legal A1 transition (approved_for_download -> downloaded) may not change any other column.'
        USING ERRCODE = '23514', CONSTRAINT = 'jte_a1_download_transition_scope', TABLE = 'jobtread_exports';
    END IF;
    RETURN NEW;
  END IF;

  -- Second download onward: downloadedBy/At are the FIRST actor/time and never move.
  IF OLD.status = 'downloaded' AND NEW.status = 'downloaded'
     AND NEW.downloaded_by = OLD.downloaded_by AND NEW.downloaded_at = OLD.downloaded_at
     AND to_jsonb(NEW) - gen_cols = to_jsonb(OLD) - gen_cols
  THEN RETURN NEW; END IF;

  RAISE EXCEPTION 'A1 export evidence is immutable outside the single approved_for_download -> downloaded transition.'
    USING ERRCODE = '23514', CONSTRAINT = 'jte_a1_update_forbidden', TABLE = 'jobtread_exports';
END $function$

CREATE OR REPLACE FUNCTION public.project_reopen_child_certify_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_should_certify boolean;
  v_parent_tenant uuid;
BEGIN
  -- TG_RELID, not TG_TABLE_NAME: a bare name match would treat ANY relation named
  -- e.g. 'field_tasks' (a same-named temp table, or one in another schema, with this
  -- same function attached to its own trigger) as if it were the real
  -- public.field_tasks. Comparing TG_RELID against the specific, schema-qualified
  -- OID of each of the 3 real tables authenticates the actual invoking relation, not
  -- just its name. IF/ELSIF by relation, never a single CASE expression: a CASE's
  -- branches all resolve field references against the bound record regardless of
  -- which WHEN is selected, so a branch naming a column absent from another table's
  -- row type (e.g. closed_at, which only project_closeouts has) would fail
  -- unconditionally inside a CASE even when never reached. Separate IF/ELSIF
  -- statements genuinely short-circuit per branch in PL/pgSQL.
  IF TG_RELID = 'public.field_tasks'::regclass THEN
    v_should_certify := true;
  ELSIF TG_RELID = 'public.project_cost_actuals'::regclass THEN
    v_should_certify := true;
  ELSIF TG_RELID = 'public.project_closeouts'::regclass THEN
    v_should_certify := (NEW.closed_at IS NOT NULL);
  ELSE
    v_should_certify := false;
  END IF;
  IF NOT v_should_certify THEN RETURN NEW; END IF;

  -- Lock and read the parent distinctly from the tenant check below, so a
  -- not-found parent and a tenant mismatch are two distinguishable failures, not
  -- one conflated condition.
  SELECT tenant_id INTO v_parent_tenant FROM public.projects WHERE id = NEW.project_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Child row references a project that does not exist.'
      USING ERRCODE = '42501', CONSTRAINT = 'project_reopen_child_parent_not_found';
  END IF;
  IF v_parent_tenant IS NULL OR NEW.tenant_id IS DISTINCT FROM v_parent_tenant THEN
    RAISE EXCEPTION 'Child row tenant does not match its parent project tenant.'
      USING ERRCODE = '42501', CONSTRAINT = 'project_reopen_child_tenant_mismatch';
  END IF;

  -- Idempotent, conditional: a row already certified is left alone, avoiding an
  -- unnecessary write/audit-adjacent trigger fan-out on every child touch.
  UPDATE public.projects SET provenance_state = 'operational_confirmed'
    WHERE id = NEW.project_id AND provenance_state <> 'operational_confirmed';
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.structr_guard_approved_estimate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE parent public.estimate_drafts;child public.estimate_drafts;has_evidence boolean;protected_old jsonb;protected_new jsonb;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.a1_version_request_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.estimate_drafts s WHERE s.supersedes_id=OLD.id AND s.a1_version_request_id IS NOT NULL) THEN RAISE EXCEPTION 'A1_VERSION_IDENTITY_PERMANENT' USING ERRCODE='23514';END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status IN ('approved','internally_approved','internal_approval_revoked') THEN RAISE EXCEPTION 'A1_DECISION_REQUIRES_REVIEWED_DRAFT' USING ERRCODE='23514';END IF;
  IF NEW.a1_version_request_id IS NOT NULL THEN
   SELECT * INTO parent FROM public.estimate_drafts WHERE id=NEW.supersedes_id FOR KEY SHARE;
   IF NOT FOUND OR parent.tenant_id IS DISTINCT FROM NEW.tenant_id OR parent.project_id IS DISTINCT FROM NEW.project_id OR parent.client_id IS DISTINCT FROM NEW.client_id OR parent.superseded_by IS NOT NULL THEN RAISE EXCEPTION 'A1_VERSION_PARENT_INVALID' USING ERRCODE='23514';END IF;
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.status='approved' AND OLD.status IS DISTINCT FROM 'approved' THEN RAISE EXCEPTION 'A1_LEGACY_APPROVAL_WRITE_DISABLED' USING ERRCODE='23514';END IF;
 IF OLD.a1_version_request_id IS NOT NULL AND (to_jsonb(OLD)-ARRAY['status','version','estimate_id','draft_data','bundle_name','zone','finish_level','trade','pricing_schema_version','channel','region','coastal_modifier','subtotal_price','subtotal_cost','final_total_price','discount_applied','discount_amount','gross_profit','gross_profit_pct','profit_shield_passed','profit_shield_min_pct','assembly_selections','line_items','intake_form_id','warnings_json','scope_draft_id','notes','metadata','bundle_id','assembly_count','approved_by','approved_at','rejected_by','rejected_at','rejection_reason','created_at','updated_at','superseded_by','locked_at','change_order_of','change_order_reason','commercial_channel','profit_shield_floor_pct','profit_shield_evaluation','pricing_snapshot']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['status','version','estimate_id','draft_data','bundle_name','zone','finish_level','trade','pricing_schema_version','channel','region','coastal_modifier','subtotal_price','subtotal_cost','final_total_price','discount_applied','discount_amount','gross_profit','gross_profit_pct','profit_shield_passed','profit_shield_min_pct','assembly_selections','line_items','intake_form_id','warnings_json','scope_draft_id','notes','metadata','bundle_id','assembly_count','approved_by','approved_at','rejected_by','rejected_at','rejection_reason','created_at','updated_at','superseded_by','locked_at','change_order_of','change_order_reason','commercial_channel','profit_shield_floor_pct','profit_shield_evaluation','pricing_snapshot']) THEN RAISE EXCEPTION 'A1_VERSION_REQUEST_IMMUTABLE' USING ERRCODE='23514';END IF;
 IF OLD.a1_version_request_id IS NULL AND NEW.a1_version_request_id IS NOT NULL THEN RAISE EXCEPTION 'A1_VERSION_REQUEST_INSERT_ONLY' USING ERRCODE='23514';END IF;
 SELECT * INTO child FROM public.estimate_drafts WHERE supersedes_id=OLD.id AND a1_version_request_id IS NOT NULL;
 IF FOUND AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.project_id IS DISTINCT FROM OLD.project_id OR NEW.client_id IS DISTINCT FROM OLD.client_id OR NEW.superseded_by IS DISTINCT FROM child.id) THEN RAISE EXCEPTION 'A1_VERSION_BACKPOINTER_IMMUTABLE' USING ERRCODE='23514';END IF;
 has_evidence:=EXISTS(SELECT 1 FROM public.estimate_internal_approval_snapshots WHERE estimate_draft_id=OLD.id);
 IF has_evidence OR OLD.status IN ('internally_approved','internal_approval_revoked') THEN
  protected_old:=to_jsonb(OLD)-ARRAY['notes','updated_at','superseded_by','status'];protected_new:=to_jsonb(NEW)-ARRAY['notes','updated_at','superseded_by','status'];
  IF protected_old IS DISTINCT FROM protected_new OR (NEW.status IS DISTINCT FROM OLD.status AND NOT(OLD.status='internally_approved' AND NEW.status='internal_approval_revoked')) THEN RAISE EXCEPTION 'A1_APPROVED_DRAFT_IMMUTABLE' USING ERRCODE='23514';END IF;
  IF NEW.superseded_by IS DISTINCT FROM OLD.superseded_by THEN
   IF OLD.superseded_by IS NOT NULL OR NEW.superseded_by IS NULL THEN RAISE EXCEPTION 'A1_VERSION_BACKPOINTER_IMMUTABLE' USING ERRCODE='23514';END IF;
  END IF;
 ELSIF NEW.status IN ('internally_approved','internal_approval_revoked') THEN
  IF OLD.status<>'draft' OR NEW.status<>'internally_approved' OR OLD.superseded_by IS NOT NULL OR (to_jsonb(NEW)-ARRAY['status','approved_by','approved_at','locked_at','profit_shield_evaluation','profit_shield_passed','profit_shield_min_pct','profit_shield_floor_pct','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','approved_by','approved_at','locked_at','profit_shield_evaluation','profit_shield_passed','profit_shield_min_pct','profit_shield_floor_pct','updated_at']) THEN RAISE EXCEPTION 'A1_INITIAL_APPROVAL_CONTENT_CHANGED' USING ERRCODE='23514';END IF;
 END IF;
 IF OLD.status='approved' AND (NEW.final_total_price IS DISTINCT FROM OLD.final_total_price OR NEW.subtotal_price IS DISTINCT FROM OLD.subtotal_price OR NEW.subtotal_cost IS DISTINCT FROM OLD.subtotal_cost OR NEW.discount_amount IS DISTINCT FROM OLD.discount_amount OR NEW.line_items IS DISTINCT FROM OLD.line_items OR NEW.assembly_selections IS DISTINCT FROM OLD.assembly_selections OR NEW.version IS DISTINCT FROM OLD.version) THEN RAISE EXCEPTION 'ESTIMATE_VERSION_LOCKED' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.structr_guard_audit_log_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'AUDIT_APPEND_ONLY: audit_log rows cannot be % — the trail is evidence.', lower(TG_OP);
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.structr_guard_calibration_event_actioned()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status = 'actioned' AND NEW.status NOT IN ('actioned', 'superseded') THEN
    RAISE EXCEPTION 'CALIBRATION_ACTIONED: event % already produced an adjustment and can only be superseded.', OLD.id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.structr_guard_closeout_closed()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status = 'closed' AND NEW.status IS DISTINCT FROM 'closed' THEN
    RAISE EXCEPTION 'CLOSEOUT_LOCKED: closeout % is closed and cannot be reopened.', OLD.id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.structr_guard_field_task_terminal()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status IN ('verified', 'cancelled') AND NEW.status IS DISTINCT FROM OLD.status THEN
    RAISE EXCEPTION 'FIELD_TASK_TERMINAL: task % is % and cannot change status. Create a new task instead.', OLD.id, OLD.status;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.structr_guard_mandatory_feature_flags()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  flags jsonb;
BEGIN
  flags := COALESCE(NEW.feature_flags, '[]'::jsonb);

  IF NOT (flags ? 'profit_shield') THEN
    RAISE EXCEPTION 'MANDATORY_FLAG_REMOVED: profit_shield cannot be disabled for tenant %.', NEW.tenant_id;
  END IF;

  IF NOT (flags ? 'audit_trail') THEN
    RAISE EXCEPTION 'MANDATORY_FLAG_REMOVED: audit_trail cannot be disabled for tenant %.', NEW.tenant_id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.structr_guard_price_adjustment_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'applied' AND OLD.status <> 'approved' THEN
      RAISE EXCEPTION 'ADJUSTMENT_NOT_APPROVED: price adjustment % cannot go from % to applied. Human approval is mandatory.', OLD.id, OLD.status;
    END IF;

    IF OLD.status = 'applied' AND NEW.status <> 'rolled_back' THEN
      RAISE EXCEPTION 'ADJUSTMENT_LOCKED: applied adjustment % can only be rolled back.', OLD.id;
    END IF;

    IF OLD.status IN ('rejected', 'rolled_back', 'expired') THEN
      RAISE EXCEPTION 'ADJUSTMENT_TERMINAL: adjustment % is % and cannot change. Propose a new one.', OLD.id, OLD.status;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.structr_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION structr_private.authenticated_session_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE claims jsonb; p record; t record; slugs text[]; result jsonb;
BEGIN
  claims:=structr_private.review_claims_v1();
  SELECT id,tenant_id,external_open_id,email,login_method,full_name,company_name,role,is_active,last_signed_in,created_at,updated_at
    INTO p FROM public.profiles WHERE external_open_id=claims->>'sub' FOR SHARE;
  IF NOT FOUND OR p.is_active IS DISTINCT FROM true OR p.tenant_id IS NULL
    OR p.tenant_id='00000000-0000-0000-0000-000000000000'::uuid OR p.id='00000000-0000-0000-0000-000000000000'::uuid THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT id,is_active INTO t FROM public.tenants WHERE id=p.tenant_id FOR SHARE;
  IF NOT FOUND OR t.is_active IS DISTINCT FROM true THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  slugs:=structr_private.review_permissions_v1(p.role);
  result:=pg_catalog.jsonb_build_object('version','structr-authenticated-session-v1',
    'profile',structr_private.review_projection_v1(pg_catalog.to_jsonb(p),ARRAY['last_signed_in','created_at','updated_at'],ARRAY[]::text[]),
    'tenantId',t.id,'permissions',pg_catalog.jsonb_build_object('slugs',slugs,'isPlatformAdmin',coalesce(p.role='admin',false)));
  PERFORM structr_private.review_claims_v1();
  RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION structr_private.estimate_draft_read_v1(command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE claims jsonb; actor record; tenant record; draft record; project record; membership record;
  draft_id uuid; history_id uuid; allowed boolean; projected jsonb:='{}'; item record; key text; pieces text[]; i integer; v jsonb; result jsonb;
BEGIN
  claims:=structr_private.review_claims_v1();
  IF pg_catalog.jsonb_typeof(command) IS DISTINCT FROM 'object' OR command-ARRAY['id']<>'{}'::jsonb
    OR NOT command ? 'id' OR pg_catalog.jsonb_typeof(command->'id') IS DISTINCT FROM 'string'
    -- General getById keeps its existing Zod UUID contract: mixed case, NIL and
    -- lowercase MAX are valid inputs. The uuid cast normalizes only this path.
    OR (command->>'id') !~ '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$' THEN
    RAISE EXCEPTION 'INTERNAL_APPROVAL_INPUT_INVALID' USING ERRCODE='P0001'; END IF;
  draft_id:=(command->>'id')::uuid;
  -- Normative V3.1 identity order: config -> profile -> tenant SHARE precedes
  -- business reads. General project/draft/membership/RBAC reads take no locks.
  SELECT id,tenant_id,external_open_id,role,is_active INTO actor FROM public.profiles WHERE external_open_id=claims->>'sub' FOR SHARE;
  IF NOT FOUND OR actor.is_active IS DISTINCT FROM true OR actor.tenant_id IS NULL
    OR actor.id='00000000-0000-0000-0000-000000000000'::uuid OR actor.tenant_id='00000000-0000-0000-0000-000000000000'::uuid THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT id,is_active INTO tenant FROM public.tenants WHERE id=actor.tenant_id FOR SHARE;
  IF NOT FOUND OR tenant.is_active IS DISTINCT FROM true THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT id,tenant_id,estimate_id,project_id,status,source,draft_data,bundle_name,zone,finish_level,trade,pricing_schema_version,channel,region,created_by,coastal_modifier,subtotal_price,subtotal_cost,final_total_price,discount_applied,discount_amount,gross_profit,gross_profit_pct,profit_shield_passed,profit_shield_min_pct,assembly_selections,line_items,intake_form_id,warnings_json,scope_draft_id,notes,metadata,bundle_id,client_id,assembly_count,approved_by,approved_at,rejected_by,rejected_at,rejection_reason,created_at,updated_at,version,superseded_by,supersedes_id,locked_at,change_order_of,change_order_reason,commercial_channel,profit_shield_floor_pct,profit_shield_evaluation,pricing_snapshot,a1_version_request_id,a1_version_request_hash INTO draft FROM public.estimate_drafts WHERE id=draft_id;
  IF NOT FOUND OR draft.project_id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0001'; END IF;
  SELECT id,tenant_id,owner_user_id INTO project FROM public.projects WHERE id=draft.project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0001'; END IF;
  IF project.tenant_id IS DISTINCT FROM actor.tenant_id THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='P0001'; END IF;
  -- Preserve the existing pool access semantics: authorization is on project,
  -- not draft.tenant_id or deleted_at; nullable active membership is accepted.
  IF actor.role IS DISTINCT FROM 'admin' AND project.owner_user_id IS DISTINCT FROM actor.id THEN
    SELECT project_role,permissions,is_active INTO membership FROM public.project_members
      WHERE project_id=project.id AND user_id=actor.id LIMIT 1;
    IF FOUND AND membership.is_active IS DISTINCT FROM false THEN
      allowed:=(membership.project_role IN ('owner','manager','estimator','field','viewer')
        OR (pg_catalog.jsonb_typeof(membership.permissions)='array' AND membership.permissions @> '["read"]'::jsonb));
    ELSE
      SELECT EXISTS(SELECT 1 FROM public.roles r JOIN public.role_permissions rp ON rp.role_id=r.id
        JOIN public.permissions p ON p.id=rp.permission_id
        WHERE r.name=actor.role AND p.resource='project' AND p.action='read') INTO allowed;
    END IF;
    IF allowed IS DISTINCT FROM true THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='P0001'; END IF;
  END IF;
  SELECT id INTO history_id FROM public.historical_estimate_imports WHERE estimate_draft_id=draft.id LIMIT 1;
  -- Shallow wire formatting is inline: this owner has no projection/helper grant.
  FOR item IN SELECT * FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(draft)) LOOP
    pieces:=pg_catalog.string_to_array(item.key,'_'); key:=pieces[1];
    FOR i IN 2..pg_catalog.cardinality(pieces) LOOP key:=key||pg_catalog.initcap(pieces[i]); END LOOP;
    v:=item.value;
    IF v<>'null'::jsonb AND item.key=ANY(ARRAY['approved_at','rejected_at','created_at','updated_at','locked_at']) THEN
      v:=pg_catalog.to_jsonb(pg_catalog.to_char((v#>>'{}')::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
    ELSIF v<>'null'::jsonb AND item.key=ANY(ARRAY['coastal_modifier','subtotal_price','subtotal_cost','final_total_price','discount_amount','gross_profit','gross_profit_pct','profit_shield_min_pct','profit_shield_floor_pct']) THEN
      v:=pg_catalog.to_jsonb(v#>>'{}');
    END IF;
    projected:=projected||pg_catalog.jsonb_build_object(key,v);
  END LOOP;
  -- F2 addendum: only this operational best-effort insert is exception-contained.
  BEGIN
    INSERT INTO public.audit_logs(user_id,action,table_name,record_id,old_values,new_values,created_at)
      VALUES(actor.id,'estimate_viewed','estimate_drafts',draft.id,NULL,
        pg_catalog.jsonb_build_object('bundleName',draft.bundle_name,'status',draft.status,'source',draft.source,'pricingSchemaVersion',draft.pricing_schema_version),pg_catalog.now());
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  PERFORM structr_private.review_claims_v1();
  result:=pg_catalog.jsonb_build_object('version','structr-authenticated-estimate-read-v1',
    'context',pg_catalog.jsonb_build_object('actorId',actor.id,'tenantId',actor.tenant_id),
    'draft',projected,'historicalImportId',history_id);
  RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION structr_private.intake_create_v1(preimage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
#variable_conflict use_column
DECLARE claims jsonb; command jsonb; p jsonb; customer jsonb; actor record; tenant record; slugs text[];
  request_id uuid; fingerprint text; full_name text; c record; project record; form record; audit record; evidence record;
  client_json jsonb; project_json jsonb; intake_json jsonb; expected jsonb; form_data jsonb;
  audit_ids uuid[]:='{}'; audit_rows jsonb:='[]'; found_count integer:=0;
  error_schema text; error_table text; error_constraint text; error_state text; error_message text;
BEGIN
  claims:=structr_private.review_claims_v1();
  command:=structr_private.intake_preimage_v1(preimage);
  SELECT id,tenant_id,external_open_id,role,is_active INTO actor FROM public.profiles WHERE external_open_id=claims->>'sub' FOR SHARE;
  IF NOT FOUND OR actor.is_active IS DISTINCT FROM true OR actor.tenant_id IS NULL
    OR actor.id='00000000-0000-0000-0000-000000000000'::uuid OR actor.tenant_id='00000000-0000-0000-0000-000000000000'::uuid THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT id,is_active INTO tenant FROM public.tenants WHERE id=actor.tenant_id FOR SHARE;
  IF NOT FOUND OR tenant.is_active IS DISTINCT FROM true OR command->>'tenantId' IS DISTINCT FROM actor.tenant_id::text
    OR command->>'userId' IS DISTINCT FROM actor.id::text THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF actor.role IS DISTINCT FROM 'admin' THEN
    slugs:=structr_private.review_permissions_v1(actor.role);
    IF NOT ('client:write'=ANY(slugs)) AND EXISTS(SELECT 1 FROM pg_catalog.unnest(slugs) slug WHERE slug LIKE 'client:%') THEN
      RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  END IF;
  request_id:=(command->>'requestId')::uuid;
  fingerprint:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(preimage,'UTF8')),'hex');
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(command->>'tenantId'),pg_catalog.hashtext(command->>'requestId'));
  PERFORM structr_private.review_claims_v1();
  SELECT id,tenant_id,lead_id,project_id,status,form_data,created_at,updated_at INTO form
    FROM public.intake_forms WHERE id=request_id AND tenant_id=actor.tenant_id FOR SHARE;
  IF FOUND THEN
    IF form.form_data->>'creationFingerprint' IS DISTINCT FROM fingerprint THEN
      RAISE EXCEPTION 'INTAKE_FORMATION_CONFLICT' USING ERRCODE='P0001'; END IF;
    PERFORM structr_private.review_claims_v1();
    RETURN pg_catalog.jsonb_build_object('version','structr-authenticated-intake-create-v1',
      'context',pg_catalog.jsonb_build_object('actorId',actor.id,'tenantId',actor.tenant_id),
      'intake',structr_private.review_projection_v1(pg_catalog.to_jsonb(form),ARRAY['created_at','updated_at'],ARRAY[]::text[]));
  END IF;
  -- Existence only. Never project another tenant's row into the response.
  IF EXISTS(SELECT 1 FROM public.intake_forms WHERE id=request_id) THEN
    RAISE EXCEPTION 'INTAKE_FORMATION_CONFLICT' USING ERRCODE='P0001'; END IF;
  p:=command->'newProject'; customer:=p->'client'; full_name:=(customer->>'firstName')||' '||(customer->>'lastName');
  PERFORM structr_private.review_claims_v1();
  INSERT INTO public.clients(tenant_id,name,email,phone,address,city,state,zip)
    VALUES(actor.tenant_id,full_name,customer->>'email',customer->>'phone',p->>'address',p->>'city',p->>'state',p->>'zip')
    RETURNING id,tenant_id,name,email,phone,company,address,city,state,zip,notes,is_active,deleted_at,created_at,updated_at,client_type,commercial_channel,source_channel,email_normalized,phone_normalized,origin_lead_id INTO c;
  expected:=pg_catalog.jsonb_build_object('tenant_id',actor.tenant_id,'name',full_name,'email',customer->>'email','phone',customer->>'phone',
    'address',p->>'address','city',p->>'city','state',p->>'state','zip',p->>'zip','is_active',true,
    'company',NULL,'notes',NULL,'deleted_at',NULL,'client_type',NULL,'commercial_channel',NULL,'source_channel',NULL,'email_normalized',NULL,'phone_normalized',NULL,'origin_lead_id',NULL);
  IF NOT FOUND OR c.id IS NULL OR pg_catalog.to_jsonb(c)-ARRAY['id','created_at','updated_at'] IS DISTINCT FROM expected
    OR c.created_at IS DISTINCT FROM pg_catalog.transaction_timestamp() OR c.updated_at IS DISTINCT FROM c.created_at THEN
    RAISE EXCEPTION 'INTAKE_FORMATION_INTEGRITY_VIOLATION' USING ERRCODE='P0001'; END IF;
  client_json:=structr_private.review_projection_v1(pg_catalog.to_jsonb(c),ARRAY['created_at','updated_at','deleted_at'],ARRAY[]::text[]);
  INSERT INTO public.audit_logs(user_id,action,table_name,record_id,old_values,new_values,ip_address,user_agent)
    VALUES(actor.id,'client.create','clients',c.id,NULL,client_json,NULL,NULL)
    RETURNING id,user_id,action,table_name,record_id,old_values,new_values,ip_address,user_agent,created_at INTO audit;
  IF NOT FOUND THEN RAISE EXCEPTION 'INTAKE_FORMATION_INTEGRITY_VIOLATION' USING ERRCODE='P0001'; END IF;
  audit_ids:=pg_catalog.array_append(audit_ids,audit.id); audit_rows:=audit_rows||pg_catalog.jsonb_build_array(pg_catalog.to_jsonb(audit));

  INSERT INTO public.projects(tenant_id,owner_user_id,client_id,client_name,client_email,name,project_type,status,channel,address,city,county,state,zip)
    VALUES(actor.tenant_id,actor.id,c.id,full_name,customer->>'email',p->>'name',p->>'projectType','intake',COALESCE(command->>'channel','direct'),p->>'address',p->>'city',p->>'county',p->>'state',p->>'zip')
    RETURNING id,tenant_id,name,client_id,owner_user_id,client_name,client_email,address,city,state,zip,project_type,channel,status,lead_id,jobtread_id,estimated_total,actual_total,variance_pct,start_date,end_date,notes,county,zone,region,finish_level,pricing_schema_version,zone_modifier_snapshot,geocode_confidence,geocode_source,geocoded_address,geocoded_at,client_type,commercial_channel,source_channel,address_normalized,latitude,longitude,geo_warnings,geo_risk_class,updated_by,variance_threshold_pct,committed_cost_cents,approved_budget_cents,change_order_budget_cents,field_started_at,field_completed_at,closed_at,provenance_state,calibrated_at,scope_completeness_score,realized_gross_profit_pct,deleted_at,created_at,updated_at INTO project;
  expected:=pg_catalog.jsonb_build_object('tenant_id',actor.tenant_id,'owner_user_id',actor.id,'client_id',c.id,'client_name',full_name,
    'client_email',customer->>'email','name',p->>'name','project_type',p->>'projectType','status','intake','channel',COALESCE(command->>'channel','direct'),
    'address',p->>'address','city',p->>'city','county',p->>'county','state',p->>'state','zip',p->>'zip',
    'provenance_state','formation_only','variance_threshold_pct',10,'committed_cost_cents',0,'change_order_budget_cents',0);
  IF NOT FOUND OR project.id IS NULL OR project.created_at IS DISTINCT FROM pg_catalog.transaction_timestamp()
    OR project.updated_at IS DISTINCT FROM project.created_at
    OR pg_catalog.jsonb_strip_nulls(pg_catalog.to_jsonb(project)-ARRAY['id','created_at','updated_at']) IS DISTINCT FROM pg_catalog.jsonb_strip_nulls(expected) THEN
    RAISE EXCEPTION 'INTAKE_FORMATION_INTEGRITY_VIOLATION' USING ERRCODE='P0001'; END IF;
  project_json:=structr_private.review_projection_v1(pg_catalog.to_jsonb(project),
    ARRAY['created_at','updated_at','deleted_at','geocoded_at','field_started_at','field_completed_at','closed_at','calibrated_at'],
    ARRAY['estimated_total','actual_total','variance_pct','latitude','longitude','variance_threshold_pct','scope_completeness_score','realized_gross_profit_pct']);
  INSERT INTO public.audit_logs(user_id,action,table_name,record_id,old_values,new_values,ip_address,user_agent)
    VALUES(actor.id,'project.create','projects',project.id,NULL,project_json,NULL,NULL)
    RETURNING id,user_id,action,table_name,record_id,old_values,new_values,ip_address,user_agent,created_at INTO audit;
  IF NOT FOUND THEN RAISE EXCEPTION 'INTAKE_FORMATION_INTEGRITY_VIOLATION' USING ERRCODE='P0001'; END IF;
  audit_ids:=pg_catalog.array_append(audit_ids,audit.id); audit_rows:=audit_rows||pg_catalog.jsonb_build_array(pg_catalog.to_jsonb(audit));
  form_data:=pg_catalog.jsonb_build_object('channel',COALESCE(command->>'channel','direct'),'serviceType',command->>'serviceType',
    'area',command->>'area','finishLevel',COALESCE(command->>'finishLevel','standard'),'condition',command->>'condition',
    'notes',command->>'notes','rawPayload',command->'rawPayload','clientId',c.id,'creationFingerprint',fingerprint);
  BEGIN
    INSERT INTO public.intake_forms(id,tenant_id,lead_id,project_id,status,form_data)
      VALUES(request_id,actor.tenant_id,NULL,project.id,'draft',form_data)
      RETURNING id,tenant_id,lead_id,project_id,status,form_data,created_at,updated_at INTO form;
  EXCEPTION WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS error_schema=SCHEMA_NAME,error_table=TABLE_NAME,error_constraint=CONSTRAINT_NAME;
    -- Only this exact INSERT's global request PK can be the stale-snapshot race.
    -- Re-raise aborts the entire RPC; the transport retries its whole transaction.
    IF error_schema='public' AND error_table='intake_forms' AND error_constraint='intake_forms_pkey' THEN
      RAISE EXCEPTION 'INTAKE_FORMATION_SERIALIZATION_RETRY' USING ERRCODE='40001'; END IF;
    RAISE;
  END;
  IF NOT FOUND OR form.id IS DISTINCT FROM request_id OR form.tenant_id IS DISTINCT FROM actor.tenant_id
    OR form.project_id IS DISTINCT FROM project.id OR form.lead_id IS NOT NULL OR form.status IS DISTINCT FROM 'draft'
    OR form.form_data IS DISTINCT FROM form_data OR form.created_at IS DISTINCT FROM pg_catalog.transaction_timestamp()
    OR form.updated_at IS DISTINCT FROM form.created_at THEN
    RAISE EXCEPTION 'INTAKE_FORMATION_INTEGRITY_VIOLATION' USING ERRCODE='P0001'; END IF;
  intake_json:=structr_private.review_projection_v1(pg_catalog.to_jsonb(form),ARRAY['created_at','updated_at'],ARRAY[]::text[]);
  INSERT INTO public.audit_logs(user_id,action,table_name,record_id,old_values,new_values,ip_address,user_agent)
    VALUES(actor.id,'intake.create','intake_forms',form.id,NULL,intake_json,NULL,NULL)
    RETURNING id,user_id,action,table_name,record_id,old_values,new_values,ip_address,user_agent,created_at INTO audit;
  IF NOT FOUND THEN RAISE EXCEPTION 'INTAKE_FORMATION_INTEGRITY_VIOLATION' USING ERRCODE='P0001'; END IF;
  audit_ids:=pg_catalog.array_append(audit_ids,audit.id); audit_rows:=audit_rows||pg_catalog.jsonb_build_array(pg_catalog.to_jsonb(audit));

  -- Also flush a deferred trigger introduced by later authorized DDL. There is
  -- no business DML after this barrier; the readback observes its effective rows.
  SET CONSTRAINTS ALL IMMEDIATE;
  -- Read every just-created snapshot back after all audit triggers have run.
  SELECT id,tenant_id,name,email,phone,company,address,city,state,zip,notes,is_active,deleted_at,created_at,updated_at,client_type,commercial_channel,source_channel,email_normalized,phone_normalized,origin_lead_id INTO evidence FROM public.clients WHERE id=c.id;
  IF NOT FOUND OR pg_catalog.to_jsonb(evidence) IS DISTINCT FROM pg_catalog.to_jsonb(c) THEN RAISE EXCEPTION 'INTAKE_FORMATION_INTEGRITY_VIOLATION' USING ERRCODE='P0001'; END IF;
  SELECT id,tenant_id,name,client_id,owner_user_id,client_name,client_email,address,city,state,zip,project_type,channel,status,lead_id,jobtread_id,estimated_total,actual_total,variance_pct,start_date,end_date,notes,county,zone,region,finish_level,pricing_schema_version,zone_modifier_snapshot,geocode_confidence,geocode_source,geocoded_address,geocoded_at,client_type,commercial_channel,source_channel,address_normalized,latitude,longitude,geo_warnings,geo_risk_class,updated_by,variance_threshold_pct,committed_cost_cents,approved_budget_cents,change_order_budget_cents,field_started_at,field_completed_at,closed_at,provenance_state,calibrated_at,scope_completeness_score,realized_gross_profit_pct,deleted_at,created_at,updated_at INTO evidence FROM public.projects WHERE id=project.id;
  IF NOT FOUND OR pg_catalog.to_jsonb(evidence) IS DISTINCT FROM pg_catalog.to_jsonb(project) THEN RAISE EXCEPTION 'INTAKE_FORMATION_INTEGRITY_VIOLATION' USING ERRCODE='P0001'; END IF;
  SELECT id,tenant_id,lead_id,project_id,status,form_data,created_at,updated_at INTO evidence FROM public.intake_forms WHERE id=form.id;
  IF NOT FOUND OR pg_catalog.to_jsonb(evidence) IS DISTINCT FROM pg_catalog.to_jsonb(form) THEN RAISE EXCEPTION 'INTAKE_FORMATION_INTEGRITY_VIOLATION' USING ERRCODE='P0001'; END IF;
  FOR evidence IN SELECT id,user_id,action,table_name,record_id,old_values,new_values,ip_address,user_agent,created_at FROM public.audit_logs WHERE id=ANY(audit_ids) LOOP
    found_count:=found_count+1;
    IF NOT (audit_rows @> pg_catalog.jsonb_build_array(pg_catalog.to_jsonb(evidence)))
      OR evidence.user_id IS DISTINCT FROM actor.id OR evidence.old_values IS NOT NULL
      OR evidence.ip_address IS NOT NULL OR evidence.user_agent IS NOT NULL OR evidence.created_at IS DISTINCT FROM pg_catalog.transaction_timestamp()
      OR ((evidence.id=audit_ids[1] AND evidence.action='client.create' AND evidence.table_name='clients' AND evidence.record_id=c.id AND evidence.new_values=client_json)
        OR (evidence.id=audit_ids[2] AND evidence.action='project.create' AND evidence.table_name='projects' AND evidence.record_id=project.id AND evidence.new_values=project_json)
        OR (evidence.id=audit_ids[3] AND evidence.action='intake.create' AND evidence.table_name='intake_forms' AND evidence.record_id=form.id AND evidence.new_values=intake_json)) IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'INTAKE_FORMATION_INTEGRITY_VIOLATION' USING ERRCODE='P0001'; END IF;
  END LOOP;
  IF found_count<>3 THEN RAISE EXCEPTION 'INTAKE_FORMATION_INTEGRITY_VIOLATION' USING ERRCODE='P0001'; END IF;
  PERFORM structr_private.review_claims_v1();
  RETURN pg_catalog.jsonb_build_object('version','structr-authenticated-intake-create-v1',
    'context',pg_catalog.jsonb_build_object('actorId',actor.id,'tenantId',actor.tenant_id),'intake',intake_json);
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS error_state=RETURNED_SQLSTATE,error_message=MESSAGE_TEXT;
  IF error_state IN ('40001','40P01') THEN RAISE EXCEPTION 'INTAKE_FORMATION_TRANSACTION_RETRY' USING ERRCODE=error_state;
  ELSIF error_state='42501' THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501';
  ELSIF error_state='P0001' AND error_message IN ('INTAKE_FORMATION_INPUT_INVALID','INTAKE_FORMATION_CONFLICT','INTAKE_FORMATION_INTEGRITY_VIOLATION') THEN
    RAISE EXCEPTION '%',error_message USING ERRCODE='P0001';
  ELSE RAISE EXCEPTION 'INTAKE_FORMATION_INTEGRITY_VIOLATION' USING ERRCODE='P0001'; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION structr_private.intake_preimage_v1(preimage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c jsonb; p jsonb; customer jsonb; item record;
BEGIN
  IF preimage IS NULL OR pg_catalog.octet_length(preimage)>65536 OR NOT (preimage IS JSON OBJECT WITH UNIQUE KEYS) THEN
    RAISE EXCEPTION 'INTAKE_FORMATION_INPUT_INVALID' USING ERRCODE='P0001'; END IF;
  BEGIN c:=preimage::jsonb;
  EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'INTAKE_FORMATION_INPUT_INVALID' USING ERRCODE='P0001'; END;
  FOR item IN WITH RECURSIVE nodes(value,depth) AS (
    SELECT c,1 UNION ALL
    SELECT child.value,nodes.depth+1 FROM nodes CROSS JOIN LATERAL (
      SELECT value FROM pg_catalog.jsonb_each(CASE WHEN pg_catalog.jsonb_typeof(nodes.value)='object' THEN nodes.value ELSE '{}'::jsonb END)
      UNION ALL SELECT value FROM pg_catalog.jsonb_array_elements(CASE WHEN pg_catalog.jsonb_typeof(nodes.value)='array' THEN nodes.value ELSE '[]'::jsonb END)
    ) child WHERE nodes.depth<=16
  ) SELECT value,depth FROM nodes LOOP
    IF item.depth>16 AND pg_catalog.jsonb_typeof(item.value) IN ('object','array') THEN
      RAISE EXCEPTION 'INTAKE_FORMATION_INPUT_INVALID' USING ERRCODE='P0001'; END IF;
    -- JSONB numeric accepts magnitudes whose IEEE-754 response parse is infinite.
    -- Validate that boundary without rewriting preimage bytes or rounding values.
    -- Values below one cannot overflow; do not turn allowed underflow into error.
    IF pg_catalog.jsonb_typeof(item.value)='number' AND pg_catalog.abs((item.value#>>'{}')::numeric)>=1 THEN
      BEGIN PERFORM (item.value#>>'{}')::double precision;
      EXCEPTION WHEN numeric_value_out_of_range THEN
        RAISE EXCEPTION 'INTAKE_FORMATION_INPUT_INVALID' USING ERRCODE='P0001'; END;
    END IF;
  END LOOP;
  IF c-ARRAY['requestId','newProject','projectId','leadId','clientId','channel','serviceType','area','finishLevel','condition','notes','rawPayload','tenantId','userId']<>'{}'
    OR NOT c ?& ARRAY['requestId','newProject','serviceType','rawPayload','tenantId','userId']
    OR pg_catalog.jsonb_typeof(c->'requestId') IS DISTINCT FROM 'string'
    OR (c->>'requestId') COLLATE "C" !~ '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$'
    OR pg_catalog.jsonb_typeof(c->'tenantId') IS DISTINCT FROM 'string' OR structr_private.review_uuid_v1(c->>'tenantId') IS DISTINCT FROM true
    OR pg_catalog.jsonb_typeof(c->'userId') IS DISTINCT FROM 'string' OR structr_private.review_uuid_v1(c->>'userId') IS DISTINCT FROM true
    OR pg_catalog.jsonb_typeof(c->'rawPayload') IS DISTINCT FROM 'object'
    OR (c ? 'projectId' AND c->'projectId'<>'null') OR (c ? 'clientId' AND c->'clientId'<>'null') OR (c ? 'leadId' AND c->'leadId'<>'null')
    OR structr_private.intake_string_v1(c->'serviceType',128,false) IS DISTINCT FROM true
    OR pg_catalog.regexp_replace(c->>'serviceType',U&'[\0009-\000D\0020\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]','','g')=''
    OR (c ? 'channel' AND c->'channel' NOT IN ('"direct"','"insurance"','"commercial"'))
    OR (c ? 'finishLevel' AND c->'finishLevel' NOT IN ('"standard"','"premium"','"luxury"')) THEN
    RAISE EXCEPTION 'INTAKE_FORMATION_INPUT_INVALID' USING ERRCODE='P0001'; END IF;
  FOR item IN SELECT * FROM (VALUES ('area',255),('condition',255),('notes',65536)) fields(key,maximum) LOOP
    IF c ? item.key AND c->item.key<>'null' AND structr_private.intake_string_v1(c->item.key,item.maximum,false) IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'INTAKE_FORMATION_INPUT_INVALID' USING ERRCODE='P0001'; END IF;
  END LOOP;
  p:=c->'newProject'; customer:=p->'client';
  IF pg_catalog.jsonb_typeof(p) IS DISTINCT FROM 'object'
    OR p-ARRAY['name','projectType','client','address','city','county','state','zip']<>'{}'
    OR NOT p ?& ARRAY['name','projectType','client','address']
    OR structr_private.intake_string_v1(p->'name',255,true) IS DISTINCT FROM true
    OR structr_private.intake_string_v1(p->'address',1000,true) IS DISTINCT FROM true
    OR p->'projectType' NOT IN ('"remodel"','"repair"','"new_construction"','"addition"','"insurance_restoration"','"commercial_buildout"','"exterior"')
    OR pg_catalog.jsonb_typeof(customer) IS DISTINCT FROM 'object' OR customer-ARRAY['firstName','lastName','email','phone']<>'{}'
    OR NOT customer ?& ARRAY['firstName','lastName']
    OR structr_private.intake_string_v1(customer->'firstName',128,true) IS DISTINCT FROM true
    OR structr_private.intake_string_v1(customer->'lastName',128,true) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'INTAKE_FORMATION_INPUT_INVALID' USING ERRCODE='P0001'; END IF;
  FOR item IN SELECT * FROM (VALUES ('city',128),('county',128),('state',2),('zip',10)) fields(key,maximum) LOOP
    IF p ? item.key AND structr_private.intake_string_v1(p->item.key,item.maximum,false) IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'INTAKE_FORMATION_INPUT_INVALID' USING ERRCODE='P0001'; END IF;
  END LOOP;
  IF (customer ? 'phone' AND structr_private.intake_string_v1(customer->'phone',64,false) IS DISTINCT FROM true)
    OR (customer ? 'email' AND (structr_private.intake_string_v1(customer->'email',320,false) IS DISTINCT FROM true
      OR (customer->>'email') COLLATE "C" !~ '^(?!\.)(?!.*\.\.)([A-Za-z0-9_''+\-.]*)[A-Za-z0-9_+-]@([A-Za-z0-9][A-Za-z0-9-]*\.)+[A-Za-z]{2,}$')) THEN
    RAISE EXCEPTION 'INTAKE_FORMATION_INPUT_INVALID' USING ERRCODE='P0001'; END IF;
  RETURN c;
END;
$function$

CREATE OR REPLACE FUNCTION structr_private.internal_approval_record_v1(command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
#variable_conflict use_column
<<internal_approval_record_v1>>
DECLARE claims jsonb; actor record; tenant record; project record; draft record; client record; membership record;
  locator uuid; actor_id uuid; tenant_id uuid; draft_id uuid; permission_slugs text[];
  snapshots jsonb:='[]'; approvals jsonb:='[]'; revocations jsonb:='[]'; authors jsonb:='[]';
  evidence record; author record; author_ids uuid[]:='{}'; source_matches boolean:=NULL;
  stack uuid[]; exits boolean[]; stack_top integer; current_id uuid; exiting boolean; colors jsonb:='{}';
  seen uuid[]:='{}'; ancestor record; parent_id uuid; history record;
  result jsonb; physical_draft jsonb;
BEGIN
  claims:=structr_private.review_claims_v1();
  IF pg_catalog.jsonb_typeof(command) IS DISTINCT FROM 'object'
    OR command-ARRAY['id']<>'{}'::jsonb OR NOT command ? 'id'
    OR pg_catalog.jsonb_typeof(command->'id') IS DISTINCT FROM 'string'
    OR structr_private.review_uuid_v1(command->>'id') IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'INTERNAL_APPROVAL_INPUT_INVALID' USING ERRCODE='P0001'; END IF;
  draft_id:=(command->>'id')::uuid;
  -- V3.1 identity locks precede business: config -> profile -> tenant SHARE,
  -- then project -> draft UPDATE, client/membership/evidence SHARE.
  SELECT id,tenant_id,external_open_id,role,is_active INTO actor FROM public.profiles WHERE external_open_id=claims->>'sub' FOR SHARE;
  IF NOT FOUND OR actor.is_active IS DISTINCT FROM true OR actor.tenant_id IS NULL
    OR actor.id='00000000-0000-0000-0000-000000000000'::uuid OR actor.tenant_id='00000000-0000-0000-0000-000000000000'::uuid THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  actor_id:=actor.id; tenant_id:=actor.tenant_id;
  SELECT id,is_active INTO tenant FROM public.tenants WHERE id=tenant_id FOR SHARE;
  IF NOT FOUND OR tenant.is_active IS DISTINCT FROM true THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT project_id INTO locator FROM public.estimate_drafts WHERE id=draft_id AND estimate_drafts.tenant_id=internal_approval_record_v1.tenant_id;
  IF NOT FOUND OR locator IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0001'; END IF;
  SELECT id,tenant_id,client_id,owner_user_id,deleted_at,commercial_channel,channel,geo_risk_class,address,city,state,zip,county,latitude,longitude,geocoded_at,geocode_confidence,geocode_source,geocoded_address,zone,zone_modifier_snapshot
    INTO project FROM public.projects WHERE id=locator AND projects.tenant_id=internal_approval_record_v1.tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0001'; END IF;
  SELECT id,tenant_id,project_id,client_id,version,created_at,pricing_schema_version,source,estimate_id,intake_form_id,bundle_id,supersedes_id,change_order_of,bundle_name,notes,subtotal_price,discount_applied,discount_amount,final_total_price,subtotal_cost,line_items,assembly_selections,pricing_snapshot,draft_data,commercial_channel,channel,zone,finish_level,region,trade,coastal_modifier,scope_draft_id,assembly_count,status,superseded_by,approved_at,approved_by,locked_at
    INTO draft FROM public.estimate_drafts WHERE id=draft_id AND estimate_drafts.tenant_id=internal_approval_record_v1.tenant_id FOR UPDATE;
  IF NOT FOUND OR draft.project_id IS DISTINCT FROM project.id OR draft.client_id IS NULL OR draft.client_id IS DISTINCT FROM project.client_id THEN
    RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0001'; END IF;
  SELECT id,tenant_id,is_active,deleted_at INTO client FROM public.clients WHERE id=draft.client_id FOR SHARE;
  IF NOT FOUND OR client.tenant_id IS DISTINCT FROM tenant_id OR project.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='P0001'; END IF;
  IF actor.role IS DISTINCT FROM 'admin' AND project.owner_user_id IS DISTINCT FROM actor_id THEN
    SELECT id,tenant_id,project_role,permissions,is_active INTO membership FROM public.project_members WHERE project_id=project.id AND user_id=actor_id FOR SHARE;
    IF FOUND AND membership.tenant_id IS DISTINCT FROM tenant_id THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='P0001'; END IF;
    IF FOUND AND membership.is_active IS TRUE THEN
      IF (membership.project_role IN ('owner','manager','estimator','field','viewer') OR (pg_catalog.jsonb_typeof(membership.permissions)='array' AND membership.permissions @> '["read"]'::jsonb)) IS DISTINCT FROM true THEN
        RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='P0001'; END IF;
    ELSE
      permission_slugs:=structr_private.review_permissions_v1(actor.role);
      IF NOT ('project:read'=ANY(permission_slugs)) THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='P0001'; END IF;
    END IF;
  END IF;

  -- Evidence is found by global draft ID. Check context before returning any
  -- raw payload; Node will validate hashes, normalization, command and state.
  FOR evidence IN SELECT id,tenant_id,project_id,client_id,estimate_draft_id,created_at,updated_at,deleted_at,draft_version,contract_version,content_hash,currency_code,currency_basis,subtotal_price_minor,discount_minor,final_price_minor,estimated_cost_minor,policy_version,policy_hash,snapshot_payload,policy_evaluation,captured_by
    FROM public.estimate_internal_approval_snapshots WHERE estimate_draft_id=draft_id ORDER BY created_at,id FOR SHARE LOOP
    IF evidence.tenant_id IS DISTINCT FROM tenant_id OR evidence.project_id IS DISTINCT FROM project.id OR evidence.client_id IS DISTINCT FROM client.id
      OR evidence.snapshot_payload->'identity'->>'tenantId' IS DISTINCT FROM tenant_id::text
      OR evidence.snapshot_payload->'identity'->>'projectId' IS DISTINCT FROM project.id::text
      OR evidence.snapshot_payload->'identity'->>'clientId' IS DISTINCT FROM client.id::text
      OR evidence.snapshot_payload->'identity'->>'estimateDraftId' IS DISTINCT FROM draft_id::text
      OR evidence.snapshot_payload->'commercialContext'->'policyContext'->'projectGeo'->>'zoneTenantId' IS DISTINCT FROM tenant_id::text THEN
      RAISE EXCEPTION 'INTERNAL_APPROVAL_INTEGRITY_ERROR' USING ERRCODE='P0001'; END IF;
    snapshots:=snapshots||pg_catalog.jsonb_build_array(structr_private.review_projection_v1(pg_catalog.to_jsonb(evidence),ARRAY['created_at','updated_at','deleted_at'],ARRAY['subtotal_price_minor','discount_minor','final_price_minor','estimated_cost_minor']));
    author_ids:=pg_catalog.array_append(author_ids,evidence.captured_by);
    -- All 28 fields read by the frozen normalizer are in the exact projection.
    -- Null unused composite columns are never returned as fabricated DTO fields.
    physical_draft:=pg_catalog.to_jsonb(draft);
    BEGIN source_matches:=public.internal_approval_draft_matches_v1(pg_catalog.jsonb_populate_record(NULL::public.estimate_drafts,physical_draft),evidence.snapshot_payload,false);
    EXCEPTION WHEN data_exception OR check_violation THEN source_matches:=false; END;
  END LOOP;
  FOR evidence IN SELECT id,tenant_id,project_id,client_id,estimate_draft_id,created_at,updated_at,deleted_at,snapshot_id,request_id,request_hash,approved_by,approved_at,reason,contract_version
    FROM public.estimate_internal_approvals WHERE estimate_draft_id=draft_id ORDER BY created_at,id FOR SHARE LOOP
    IF evidence.tenant_id IS DISTINCT FROM tenant_id OR evidence.project_id IS DISTINCT FROM project.id OR evidence.client_id IS DISTINCT FROM client.id THEN
      RAISE EXCEPTION 'INTERNAL_APPROVAL_INTEGRITY_ERROR' USING ERRCODE='P0001'; END IF;
    approvals:=approvals||pg_catalog.jsonb_build_array(structr_private.review_projection_v1(pg_catalog.to_jsonb(evidence),ARRAY['created_at','updated_at','deleted_at','approved_at'],ARRAY[]::text[]));
    author_ids:=pg_catalog.array_append(author_ids,evidence.approved_by);
  END LOOP;
  FOR evidence IN SELECT id,tenant_id,project_id,client_id,estimate_draft_id,created_at,updated_at,deleted_at,approval_id,request_id,request_hash,revoked_by,revoked_at,reason,contract_version
    FROM public.estimate_internal_approval_revocations WHERE estimate_draft_id=draft_id ORDER BY created_at,id FOR SHARE LOOP
    IF evidence.tenant_id IS DISTINCT FROM tenant_id OR evidence.project_id IS DISTINCT FROM project.id OR evidence.client_id IS DISTINCT FROM client.id THEN
      RAISE EXCEPTION 'INTERNAL_APPROVAL_INTEGRITY_ERROR' USING ERRCODE='P0001'; END IF;
    revocations:=revocations||pg_catalog.jsonb_build_array(structr_private.review_projection_v1(pg_catalog.to_jsonb(evidence),ARRAY['created_at','updated_at','deleted_at','revoked_at'],ARRAY[]::text[]));
    author_ids:=pg_catalog.array_append(author_ids,evidence.revoked_by);
  END LOOP;
  FOR author IN SELECT id,tenant_id FROM public.profiles WHERE id=ANY(author_ids) ORDER BY id FOR SHARE LOOP
    IF author.tenant_id IS DISTINCT FROM tenant_id THEN RAISE EXCEPTION 'INTERNAL_APPROVAL_INTEGRITY_ERROR' USING ERRCODE='P0001'; END IF;
    authors:=authors||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('id',author.id,'tenantId',author.tenant_id));
  END LOOP;
  IF pg_catalog.jsonb_array_length(authors)<>(SELECT count(DISTINCT x) FROM pg_catalog.unnest(author_ids) x)
    OR pg_catalog.jsonb_array_length(snapshots)>1 OR pg_catalog.jsonb_array_length(approvals)>1 OR pg_catalog.jsonb_array_length(revocations)>1 THEN
    RAISE EXCEPTION 'INTERNAL_APPROVAL_INTEGRITY_ERROR' USING ERRCODE='P0001'; END IF;

  IF snapshots='[]'::jsonb AND approvals='[]'::jsonb AND revocations='[]'::jsonb THEN
    IF draft.status IN ('internally_approved','internal_approval_revoked') THEN
      RAISE EXCEPTION 'INTERNAL_APPROVAL_INTEGRITY_ERROR' USING ERRCODE='P0001'; END IF;
  ELSE
    IF pg_catalog.jsonb_array_length(snapshots)<>1 OR pg_catalog.jsonb_array_length(approvals)<>1 THEN
      RAISE EXCEPTION 'INTERNAL_APPROVAL_INTEGRITY_ERROR' USING ERRCODE='P0001'; END IF;
    -- A record without evidence returns none, even for historical/legacy input.
    -- Lineage authority is required only when validating persisted A1 evidence.
  -- Iterative DFS preserves both derivation edges, detects cycles, deduplicates
  -- DAG nodes and caps distinct nodes at 1000 without recursive stack growth.
  stack:=ARRAY[draft_id]; exits:=ARRAY[false];
  WHILE pg_catalog.cardinality(stack)>0 LOOP
    stack_top:=pg_catalog.cardinality(stack); current_id:=stack[stack_top]; exiting:=exits[stack_top];
    stack:=stack[1:stack_top-1]; exits:=exits[1:stack_top-1];
    IF exiting THEN colors:=colors||pg_catalog.jsonb_build_object(current_id::text,'black'); CONTINUE; END IF;
    IF colors->>current_id::text='gray' THEN RAISE EXCEPTION 'INTERNAL_APPROVAL_CONTENT_UNRESOLVED' USING ERRCODE='P0001'; END IF;
    IF colors->>current_id::text='black' THEN CONTINUE; END IF;
    IF pg_catalog.cardinality(seen)>=1000 THEN RAISE EXCEPTION 'INTERNAL_APPROVAL_CONTENT_UNRESOLVED' USING ERRCODE='P0001'; END IF;
    SELECT id,tenant_id,project_id,client_id,source,supersedes_id,change_order_of INTO ancestor FROM public.estimate_drafts WHERE id=current_id;
    IF NOT FOUND OR ancestor.tenant_id IS DISTINCT FROM tenant_id OR ancestor.project_id IS DISTINCT FROM project.id OR ancestor.client_id IS DISTINCT FROM client.id THEN
      RAISE EXCEPTION 'INTERNAL_APPROVAL_CONTENT_UNRESOLVED' USING ERRCODE='P0001'; END IF;
    IF ancestor.source='historical_import' THEN RAISE EXCEPTION 'HISTORICAL_AUTHORITY_NOT_AVAILABLE' USING ERRCODE='P0001'; END IF;
    IF ancestor.source IS NULL OR ancestor.source NOT IN ('assembly_calculator','scope_draft','version','change_order')
      OR (ancestor.source='version' AND ancestor.supersedes_id IS NULL) OR (ancestor.source='change_order' AND ancestor.change_order_of IS NULL) THEN
      RAISE EXCEPTION 'INTERNAL_APPROVAL_CONTENT_UNRESOLVED' USING ERRCODE='P0001'; END IF;
    seen:=pg_catalog.array_append(seen,current_id); colors:=colors||pg_catalog.jsonb_build_object(current_id::text,'gray');
    stack:=pg_catalog.array_append(stack,current_id); exits:=pg_catalog.array_append(exits,true);
    FOREACH parent_id IN ARRAY ARRAY[ancestor.change_order_of,ancestor.supersedes_id] LOOP
      IF parent_id IS NOT NULL THEN stack:=pg_catalog.array_append(stack,parent_id); exits:=pg_catalog.array_append(exits,false); END IF;
    END LOOP;
  END LOOP;
  -- Deliberately no tenant filter: contradictory H1 evidence must cause denial.
  FOR history IN SELECT id FROM public.historical_estimate_imports WHERE estimate_draft_id=ANY(seen) ORDER BY id FOR SHARE LOOP
    RAISE EXCEPTION 'HISTORICAL_AUTHORITY_NOT_AVAILABLE' USING ERRCODE='P0001';
  END LOOP;
  FOR ancestor IN SELECT id,tenant_id,project_id,client_id FROM public.estimate_drafts WHERE id=ANY(seen) AND id<>draft_id ORDER BY id FOR SHARE LOOP
    IF ancestor.tenant_id IS DISTINCT FROM tenant_id OR ancestor.project_id IS DISTINCT FROM project.id OR ancestor.client_id IS DISTINCT FROM client.id THEN
      RAISE EXCEPTION 'INTERNAL_APPROVAL_CONTENT_UNRESOLVED' USING ERRCODE='P0001'; END IF;
  END LOOP;

  END IF;
  PERFORM structr_private.review_claims_v1();
  result:=pg_catalog.jsonb_build_object('version','structr-authenticated-approval-record-v1',
    'context',pg_catalog.jsonb_build_object('actorId',actor_id,'tenantId',tenant_id),
    'rows',pg_catalog.jsonb_build_object(
      'draft',structr_private.review_projection_v1(pg_catalog.to_jsonb(draft),ARRAY['created_at','approved_at','locked_at'],ARRAY['subtotal_price','discount_amount','final_total_price','subtotal_cost','coastal_modifier']),
      'project',structr_private.review_projection_v1(pg_catalog.to_jsonb(project)-'owner_user_id',ARRAY['deleted_at','geocoded_at'],ARRAY['latitude','longitude']),
      'client',structr_private.review_projection_v1(pg_catalog.to_jsonb(client),ARRAY['deleted_at'],ARRAY[]::text[]),
      'tenant',pg_catalog.jsonb_build_object('id',tenant.id,'isActive',tenant.is_active),
      'profile',pg_catalog.jsonb_build_object('id',actor.id,'tenantId',actor.tenant_id,'isActive',actor.is_active)),
    'approvalEvidence',pg_catalog.jsonb_build_object('snapshots',snapshots,'approvals',approvals,'revocations',revocations,'authors',authors,'sourceMatches',source_matches));
  RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION structr_private.internal_approval_review_v1(command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
#variable_conflict use_column
<<internal_approval_review_v1>>
