   RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND OLD.is_active AND NOT NEW.is_active AND (to_jsonb(OLD)-ARRAY['is_active','updated_at'])=(to_jsonb(NEW)-ARRAY['is_active','updated_at']) THEN RETURN NEW; END IF;
